    return reverse('admin:%s_%s_change' % (self.opts.app_label,
                                           self.opts.model_name),
                   args=(quote(pk),),
                   current_app=self.model_admin.admin_site.name)

def authenticate(self, request):
    """
    Returns a `User` if a correct username and password have been supplied
    using HTTP Basic authentication.  Otherwise returns `None`.
    """
    auth = get_authorization_header(request).split()

    if not auth or auth[0].lower() != b'basic':
        return None

    if len(auth) == 1:
        msg = _('Invalid basic header. No credentials provided.')
        raise exceptions.AuthenticationFailed(msg)
    elif len(auth) > 2:
        msg = _('Invalid basic header. Credentials string should not contain spaces.')
        raise exceptions.AuthenticationFailed(msg)

    try:
        try:
            auth_decoded = base64.b64decode(auth[1]).decode('utf-8')
        except UnicodeDecodeError:
            auth_decoded = base64.b64decode(auth[1]).decode('latin-1')
        auth_parts = auth_decoded.partition(':')
    except (TypeError, UnicodeDecodeError, binascii.Error):
        msg = _('Invalid basic header. Credentials not correctly base64 encoded.')
        raise exceptions.AuthenticationFailed(msg)

    userid, password = auth_parts[0], auth_parts[2]
    return self.authenticate_credentials(userid, password, request)

def authenticate_credentials(self, userid, password, request=None):
    """
    Authenticate the userid and password against username and password
    with optional request for context.
    """
    credentials = {
        get_user_model().USERNAME_FIELD: userid,
        'password': password
    }
    user = authenticate(request=request, **credentials)

    if user is None:
        raise exceptions.AuthenticationFailed(_('Invalid username/password.'))

    if not user.is_active:
        raise exceptions.AuthenticationFailed(_('User inactive or deleted.'))

    return (user, None)

def authenticate(self, request):
    auth = get_authorization_header(request).split()

    if not auth or auth[0].lower() != self.keyword.lower().encode():
        return None

    if len(auth) == 1:
        msg = _('Invalid token header. No credentials provided.')
        raise exceptions.AuthenticationFailed(msg)
    elif len(auth) > 2:
        msg = _('Invalid token header. Token string should not contain spaces.')
        raise exceptions.AuthenticationFailed(msg)

    try:
        token = auth[1].decode()
    except UnicodeError:
        msg = _('Invalid token header. Token string should not contain invalid characters.')
        raise exceptions.AuthenticationFailed(msg)

    return self.authenticate_credentials(token)

def force_authenticate(request, user=None, token=None):
    request._force_auth_user = user
    request._force_auth_token = token

def get_response(self, request):
    # This is the simplest place we can hook into to patch the
    # request object.
    force_authenticate(request, self._force_user, self._force_token)
    return super().get_response(request)

def request(self, **kwargs):
    # Ensure that any credentials set get added to every request.
    kwargs.update(self._credentials)
    return super().request(**kwargs)

def get_authenticate_header(self, request):
    """
    If a request is unauthenticated, determine the WWW-Authenticate
    header to use for 401 responses, if any.
    """
    authenticators = self.get_authenticators()
    if authenticators:
        return authenticators[0].authenticate_header(request)

def _authenticate(self):
    """
    Attempt to authenticate the request using each authentication instance
    in turn.
    """
    for authenticator in self.authenticators:
        try:
            user_auth_tuple = authenticator.authenticate(self)
        except exceptions.APIException:
            self._not_authenticated()
            raise

        if user_auth_tuple is not None:
            self._authenticator = authenticator
            self.user, self.auth = user_auth_tuple
            return

    self._not_authenticated()

def _not_authenticated(self):
    """
    Set authenticator, user & authtoken representing an unauthenticated request.

    Defaults are None, AnonymousUser & None.
    """
    self._authenticator = None

    if api_settings.UNAUTHENTICATED_USER:
        self.user = api_settings.UNAUTHENTICATED_USER()
    else:
        self.user = None

    if api_settings.UNAUTHENTICATED_TOKEN:
        self.auth = api_settings.UNAUTHENTICATED_TOKEN()
    else:
        self.auth = None

def _reject(self, request, reason):
    # Return the failure reason instead of an HttpResponse
    return reason

def get_model(self):
    if self.model is not None:
        return self.model
    from rest_framework.authtoken.models import Token
    return Token

def authenticate_credentials(self, key):
    model = self.get_model()
    try:
        token = model.objects.select_related('user').get(key=key)
    except model.DoesNotExist:
        raise exceptions.AuthenticationFailed(_('Invalid token.'))

    if not token.user.is_active:
        raise exceptions.AuthenticationFailed(_('User inactive or deleted.'))

    return (token.user, token)

def __init__(self, enforce_csrf_checks=False, **defaults):
    super().__init__(**defaults)
    self.handler = ForceAuthClientHandler(enforce_csrf_checks)
    self._credentials = {}

def post(self, request, *args, **kwargs):
    serializer = self.get_serializer(data=request.data)
    serializer.is_valid(raise_exception=True)
    user = serializer.validated_data['user']
    token, created = Token.objects.get_or_create(user=user)
    return Response({'token': token.key})

def create_user_token(self, username, reset_token):
    user = UserModel._default_manager.get_by_natural_key(username)

    if reset_token:
        Token.objects.filter(user=user).delete()

    token = Token.objects.get_or_create(user=user)
    return token[0]

def handle(self, *args, **options):
    username = options['username']
    reset_token = options['reset_token']

    try:
        token = self.create_user_token(username, reset_token)
    except UserModel.DoesNotExist:
        raise CommandError(
            'Cannot create the Token: user {} does not exist'.format(
                username)
        )
    self.stdout.write(
        'Generated token {} for user {}'.format(token.key, username))

def get_cache_key(self, request, view):
    if request.user and request.user.is_authenticated:
        return None  # Only throttle unauthenticated requests.

    return self.cache_format % {
        'scope': self.scope,
        'ident': self.get_ident(request)
    }

def get_cache_key(self, request, view):
    if request.user and request.user.is_authenticated:
        ident = request.user.pk
    else:
        ident = self.get_ident(request)

    return self.cache_format % {
        'scope': self.scope,
        'ident': ident
    }

def get_cache_key(self, request, view):
    """
    If `view.throttle_scope` is not set, don't apply this throttle.

    Otherwise generate the unique cache key by concatenating the user id
    with the `.throttle_scope` property of the view.
    """
    if request.user and request.user.is_authenticated:
        ident = request.user.pk
    else:
        ident = self.get_ident(request)

    return self.cache_format % {
        'scope': self.scope,
        'ident': ident
    }

def authenticate(self, request):
    user = authenticate(request=request, remote_user=request.META.get(self.header))
    if user and user.is_active:
        return (user, None)

def get(self, request, *args, **kwargs):
    schema = self.schema_generator.get_schema(request, self.public)
    if schema is None:
        raise exceptions.PermissionDenied()
    return Response(schema)

def preserve_builtin_query_params(url, request=None):
    """
    Given an incoming request, and an outgoing URL representation,
    append the value of any built-in query parameters.
    """
    if request is None:
        return url

    overrides = [
        api_settings.URL_FORMAT_OVERRIDE,
    ]

    for param in overrides:
        if param and (param in request.GET):
            value = request.GET[param]
            url = replace_query_param(url, param, value)

    return url

def __init__(self, headers):
    self.msg = HeaderDict(headers)
    self.closed = False

def __or__(self, other):
    if not isinstance(other, dict):
        return NotImplemented
    new = self.__class__(self, serializer=self.serializer)
    new.update(other)
    return new

def __ror__(self, other):
    if not isinstance(other, dict):
        return NotImplemented
    new = self.__class__(other, serializer=self.serializer)
    new.update(self)
    return new

def optional_logout(request, user):
    """
    Include a logout snippet if REST framework's logout view is in the URLconf.
    """
    try:
        logout_url = reverse('rest_framework:logout')
    except NoReverseMatch:
        snippet = format_html('<li class="navbar-text">{user}</li>', user=escape(user))
        return mark_safe(snippet)

    snippet = """<li class="dropdown">
        <a href="#" class="dropdown-toggle" data-toggle="dropdown">
            {user}
            <b class="caret"></b>
        </a>
        <ul class="dropdown-menu">
            <li><a href='{href}?next={next}'>Log out</a></li>
        </ul>
    </li>"""
    snippet = format_html(snippet, user=escape(user), href=logout_url, next=escape(request.path))

    return mark_safe(snippet)

def get_environ(self, request):
    """
    Given a `requests.PreparedRequest` instance, return a WSGI environ dict.
    """
    method = request.method
    url = request.url
    kwargs = {}

    # Set request content, if any exists.
    if request.body is not None:
        if hasattr(request.body, 'read'):
            kwargs['data'] = request.body.read()
        else:
            kwargs['data'] = request.body
    if 'content-type' in request.headers:
        kwargs['content_type'] = request.headers['content-type']

    # Set request headers.
    for key, value in request.headers.items():
        key = key.upper()
        if key in ('CONNECTION', 'CONTENT-LENGTH', 'CONTENT-TYPE'):
            continue
        kwargs['HTTP_%s' % key.replace('-', '_')] = value

    return self.factory.generic(method, url, **kwargs).environ

def tearDownClass(cls):
    super().tearDownClass()
    cls._override.disable()

    if hasattr(cls, '_module_urlpatterns'):
        cls._module.urlpatterns = cls._module_urlpatterns
    else:
        del cls._module.urlpatterns

def request(self, method, url, *args, **kwargs):
    if not url.startswith('http'):
        raise ValueError('Missing "http:" or "https:". Use a fully qualified URL, eg "http://testserver%s"' % url)
    return super().request(method, url, *args, **kwargs)

def optional_login(request):
    """
    Include a login snippet if REST framework's login view is in the URLconf.
    """
    try:
        login_url = reverse('rest_framework:login')
    except NoReverseMatch:
        return ''

    snippet = "<li><a href='{href}?next={next}'>Log in</a></li>"
    snippet = format_html(snippet, href=login_url, next=escape(request.path))

    return mark_safe(snippet)

def optional_docs_login(request):
    """
    Include a login snippet if REST framework's login view is in the URLconf.
    """
    try:
        login_url = reverse('rest_framework:login')
    except NoReverseMatch:
        return 'log in'

    snippet = "<a href='{href}?next={next}'>log in</a>"
    snippet = format_html(snippet, href=login_url, next=escape(request.path))

    return mark_safe(snippet)

