def get_object_or_404(queryset, *filter_args, **filter_kwargs):
    """
    Same as Django's standard shortcut, but make sure to also raise 404
    if the filter_kwargs don't match the required types.
    """
    try:
        return _get_object_or_404(queryset, *filter_args, **filter_kwargs)
    except (TypeError, ValueError, ValidationError):
        raise Http404

def distinct(queryset, base):
    if settings.DATABASES[queryset.db]["ENGINE"] == "django.db.backends.oracle":
        # distinct analogue for Oracle users
        return base.filter(pk__in=set(queryset.values_list('pk', flat=True)))
    return queryset.distinct()

def get_default_valid_fields(self, queryset, view, context={}):
    # If `ordering_fields` is not specified, then we determine a default
    # based on the serializer class, if one exists on the view.
    if hasattr(view, 'get_serializer_class'):
        try:
            serializer_class = view.get_serializer_class()
        except AssertionError:
            # Raised by the default implementation if
            # no serializer_class was found
            serializer_class = None
    else:
        serializer_class = getattr(view, 'serializer_class', None)

    if serializer_class is None:
        msg = (
            "Cannot use %s on a view which does not have either a "
            "'serializer_class', an overriding 'get_serializer_class' "
            "or 'ordering_fields' attribute."
        )
        raise ImproperlyConfigured(msg % self.__class__.__name__)

    model_class = queryset.model
    model_property_names = [
        # 'pk' is a property added in Django's Model class, however it is valid for ordering.
        attr for attr in dir(model_class) if isinstance(getattr(model_class, attr), property) and attr != 'pk'
    ]

    return [
        (field.source.replace('.', '__') or field_name, field.label)
        for field_name, field in serializer_class(context=context).fields.items()
        if (
            not getattr(field, 'write_only', False) and
            not field.source == '*' and
            field.source not in model_property_names
        )
    ]

def get_valid_fields(self, queryset, view, context={}):
    valid_fields = getattr(view, 'ordering_fields', self.ordering_fields)

    if valid_fields is None:
        # Default to allowing filtering on serializer fields
        return self.get_default_valid_fields(queryset, view, context)

    elif valid_fields == '__all__':
        # View explicitly allows filtering on any model field
        valid_fields = [
            (field.name, field.verbose_name) for field in queryset.model._meta.fields
        ]
        valid_fields += [
            (key, key.title().split('__'))
            for key in queryset.query.annotations
        ]
    else:
        valid_fields = [
            (item, item) if isinstance(item, str) else item
            for item in valid_fields
        ]

    return valid_fields

def remove_invalid_fields(self, queryset, fields, view, request):
    valid_fields = [item[0] for item in self.get_valid_fields(queryset, view, {'request': request})]

    def term_valid(term):
        if term.startswith("-"):
            term = term[1:]
        return term in valid_fields

    return [term for term in fields if term_valid(term)]

def filter_queryset(self, request, queryset, view):
    ordering = self.get_ordering(request, queryset, view)

    if ordering:
        return queryset.order_by(*ordering)

    return queryset

def get_count(self, queryset):
    """
    Determine an object count, supporting either querysets or regular lists.
    """
    try:
        return queryset.count()
    except (AttributeError, TypeError):
        return len(queryset)

def qs_filter(queryset, **kwargs):
    try:
        return queryset.filter(**kwargs)
    except (TypeError, ValueError, DataError):
        return queryset.none()

def filter_queryset(self, value, queryset, field_name):
    """
    Filter the queryset to all instances matching the given attribute.
    """
    filter_kwargs = {'%s__%s' % (field_name, self.lookup): value}
    return qs_filter(queryset, **filter_kwargs)

def exclude_current_instance(self, queryset, instance):
    """
    If an instance is being updated, then do not include
    that instance itself as a uniqueness conflict.
    """
    if instance is not None:
        return queryset.exclude(pk=instance.pk)
    return queryset

def filter_queryset(self, attrs, queryset, serializer):
    """
    Filter the queryset to all instances matching the given attributes.
    """
    # field names => field sources
    sources = [
        serializer.fields[field_name].source
        for field_name in self.fields
    ]

    # If this is an update, then any unprovided field should
    # have it's value set based on the existing instance attribute.
    if serializer.instance is not None:
        for source in sources:
            if source not in attrs:
                attrs[source] = getattr(serializer.instance, source)

    # Determine the filter keyword arguments and filter the queryset.
    filter_kwargs = {
        source: attrs[source]
        for source in sources
    }
    return qs_filter(queryset, **filter_kwargs)

