        "The `child` argument must be an instance of `CharField`, "
        "as the hstore extension stores values as strings."
    )

def get_api_root_view(self, api_urls=None):
    """
    Return a basic root view.
    """
    api_root_dict = OrderedDict()
    list_name = self.routes[0].name
    for prefix, viewset, basename in self.registry:
        api_root_dict[prefix] = list_name.format(basename=basename)

    return self.APIRootView.as_view(api_root_dict=api_root_dict)

def _get_format_path_converter(suffix_kwarg, allowed):
    if allowed:
        if len(allowed) == 1:
            allowed_pattern = allowed[0]
        else:
            allowed_pattern = '(?:%s)' % '|'.join(allowed)
        suffix_pattern = r"\.%s/?" % allowed_pattern
    else:
        suffix_pattern = r"\.[a-z0-9]+/?"

    class FormatSuffixConverter:
        regex = suffix_pattern

        def to_python(self, value):
            return value.strip('./')

        def to_url(self, value):
            return '.' + value + '/'

    converter_name = 'drf_format_suffix'
    if allowed:
        converter_name += '_' + '_'.join(allowed)

    return converter_name, FormatSuffixConverter

def unicode_http_header(value):
    # Coerce HTTP header value to unicode.
    if isinstance(value, bytes):
        return value.decode('iso-8859-1')
    return value

def determine_version(self, request, *args, **kwargs):
    msg = '{cls}.determine_version() must be implemented.'
    raise NotImplementedError(msg.format(
        cls=self.__class__.__name__
    ))

def is_allowed_version(self, version):
    if not self.allowed_versions:
        return True
    return ((version is not None and version == self.default_version) or
            (version in self.allowed_versions))

def determine_version(self, request, *args, **kwargs):
    version = kwargs.get(self.version_param, self.default_version)
    if version is None:
        version = self.default_version

    if not self.is_allowed_version(version):
        raise exceptions.NotFound(self.invalid_version_message)
    return version

def determine_version(self, request, *args, **kwargs):
    resolver_match = getattr(request, 'resolver_match', None)
    if resolver_match is None or not resolver_match.namespace:
        return self.default_version

    # Allow for possibly nested namespaces.
    possible_versions = resolver_match.namespace.split(':')
    for version in possible_versions:
        if self.is_allowed_version(version):
            return version
    raise exceptions.NotFound(self.invalid_version_message)

def determine_version(self, request, *args, **kwargs):
    hostname, separator, port = request.get_host().partition(':')
    match = self.hostname_regex.match(hostname)
    if not match:
        return self.default_version
    version = match.group(1)
    if not self.is_allowed_version(version):
        raise exceptions.NotFound(self.invalid_version_message)
    return version

def determine_version(self, request, *args, **kwargs):
    version = request.query_params.get(self.version_param, self.default_version)
    if not self.is_allowed_version(version):
        raise exceptions.NotFound(self.invalid_version_message)
    return version

def apply_markdown(text):
    """
    Simple wrapper around :func:`markdown.markdown` to set the base level
    of '#' style headers to <h2>.
    """
    extensions = [HEADERID_EXT_PATH]
    extension_configs = {
        HEADERID_EXT_PATH: {
            LEVEL_PARAM: '2'
        }
    }
    md = markdown.Markdown(
        extensions=extensions, extension_configs=extension_configs
    )
    md_filter_add_syntax_highlight(md)
    return md.convert(text)

def md_filter_add_syntax_highlight(md):
    md.preprocessors.register(CodeBlockPreprocessor(), 'highlight', 40)
    return True

def markup_description(description):
    """
    Apply HTML markup to the given description.
    """
    if apply_markdown:
        description = apply_markdown(description)
    else:
        description = escape(description).replace('\n', '<br />')
        description = '<p>' + description + '</p>'
    return mark_safe(description)

def render_markdown(markdown_text):
    if apply_markdown is None:
        return markdown_text
    return mark_safe(apply_markdown(markdown_text))

def format_value(value):
    if getattr(value, 'is_hyperlink', False):
        name = str(value.obj)
        return mark_safe('<a href=%s>%s</a>' % (value, escape(name)))
    if value is None or isinstance(value, bool):
        return mark_safe('<code>%s</code>' % {True: 'true', False: 'false', None: 'null'}[value])
    elif isinstance(value, list):
        if any(isinstance(item, (list, dict)) for item in value):
            template = loader.get_template('rest_framework/admin/list_value.html')
        else:
            template = loader.get_template('rest_framework/admin/simple_list_value.html')
        context = {'value': value}
        return template.render(context)
    elif isinstance(value, dict):
        template = loader.get_template('rest_framework/admin/dict_value.html')
        context = {'value': value}
        return template.render(context)
    elif isinstance(value, str):
        if (
            (value.startswith('http:') or value.startswith('https:') or value.startswith('/')) and not
            re.search(r'\s', value)
        ):
            return mark_safe('<a href="{value}">{value}</a>'.format(value=escape(value)))
        elif '@' in value and not re.search(r'\s', value):
            return mark_safe('<a href="mailto:{value}">{value}</a>'.format(value=escape(value)))
        elif '\n' in value:
            return mark_safe('<pre>%s</pre>' % escape(value))
    return str(value)

def add_nested_class(value):
    if isinstance(value, dict):
        return 'class=nested'
    if isinstance(value, list) and any(isinstance(item, (list, dict)) for item in value):
        return 'class=nested'
    return ''

def pygments_highlight(text, lang, style):
    lexer = get_lexer_by_name(lang, stripall=False)
    formatter = HtmlFormatter(nowrap=True, style=style)
    return pygments.highlight(text, lexer, formatter)

def run(self, lines):
    def repl(m):
        try:
            lexer = get_lexer_by_name(m.group(1))
        except (ValueError, NameError):
            lexer = TextLexer()
        code = m.group(2).replace('\t', '    ')
        code = pygments.highlight(code, lexer, self.formatter)
        code = code.replace('\n\n', '\n&nbsp;\n').replace('\n', '<br />').replace('\\@', '@')
        return '\n\n%s\n\n' % code
    ret = self.pattern.sub(repl, "\n".join(lines))
    return ret.split("\n")

def render(self, context):
    text = self.nodelist.render(context)
    return pygments_highlight(text, self.lang, self.style)

def pygments_css(style):
    formatter = HtmlFormatter(style=style)
    return formatter.get_style_defs('.highlight')

def get_context(self, data, request):
