def force_evaluation():
    raise RuntimeError(
        'Do not evaluate the `.queryset` attribute directly, '
        'as the result will be cached and reused between requests. '
        'Use `.all()` or call `.get_queryset()` instead.'
    )

def allowed_methods(self):
    """
    Wrap Django's private `_allowed_methods` interface in a public property.
    """
    return self._allowed_methods()

def default_response_headers(self):
    headers = {
        'Allow': ', '.join(self.allowed_methods),
    }
    if len(self.renderer_classes) > 1:
        headers['Vary'] = 'Accept'
    return headers

def __exit__(self, *args, **kwarg):
    self.view.request = self.request
    self.view.action = self.action

def __call__(self, serializer_field):
    is_update = serializer_field.parent.instance is not None
    if is_update:
        raise SkipField()
    if callable(self.default):
        if getattr(self.default, 'requires_context', False):
            return self.default(serializer_field)
        else:
            return self.default()
    return self.default

def iter_options(self):
    """
    Helper method for use with templates rendering select widgets.
    """
    return iter_options(
        self.grouped_choices,
        cutoff=self.html_cutoff,
        cutoff_text=self.html_cutoff_text
    )

def get_extra_actions(self, view, status_code):
    if (status_code in (status.HTTP_401_UNAUTHORIZED, status.HTTP_403_FORBIDDEN)):
        return None
    elif not hasattr(view, 'get_extra_action_url_map'):
        return None

    return view.get_extra_action_url_map()

def has_permission(self, request, view):
    return (
        self.op1.has_permission(request, view) and
        self.op2.has_permission(request, view)
    )

def has_object_permission(self, request, view, obj):
    return (
        self.op1.has_object_permission(request, view, obj) and
        self.op2.has_object_permission(request, view, obj)
    )

def has_permission(self, request, view):
    return (
        self.op1.has_permission(request, view) or
        self.op2.has_permission(request, view)
    )

def has_object_permission(self, request, view, obj):
    return (
        self.op1.has_permission(request, view)
        and self.op1.has_object_permission(request, view, obj)
    ) or (
        self.op2.has_permission(request, view)
        and self.op2.has_object_permission(request, view, obj)
    )

def has_permission(self, request, view):
    return bool(
        request.method in SAFE_METHODS or
        request.user and
        request.user.is_authenticated
    )

def reverse(self, viewname, args=None, kwargs=None, request=None, format=None, **extra):
    if request.version is not None:
        viewname = self.get_versioned_viewname(viewname, request)
    return super().reverse(
        viewname, args, kwargs, request, format, **extra
    )

def reverse(self, viewname, args=None, kwargs=None, request=None, format=None, **extra):
    url = super().reverse(
        viewname, args, kwargs, request, format, **extra
    )
    if request.version is not None:
        return replace_query_param(url, self.version_param, request.version)
    return url

def many_init(cls, *args, **kwargs):
    """
    This method implements the creation of a `ListSerializer` parent
    class when `many=True` is used. You can customize it if you need to
    control which keyword arguments are passed to the parent, and
    which are passed to the child.

    Note that we're over-cautious in passing most arguments to both parent
    and child classes in order to try to cover the general case. If you're
    overriding this method you'll probably want something much simpler, eg:

    @classmethod
    def many_init(cls, *args, **kwargs):
        kwargs['child'] = cls()
        return CustomListSerializer(*args, **kwargs)
    """
    allow_empty = kwargs.pop('allow_empty', None)
    max_length = kwargs.pop('max_length', None)
    min_length = kwargs.pop('min_length', None)
    child_serializer = cls(*args, **kwargs)
    list_kwargs = {
        'child': child_serializer,
    }
    if allow_empty is not None:
        list_kwargs['allow_empty'] = allow_empty
    if max_length is not None:
        list_kwargs['max_length'] = max_length
    if min_length is not None:
        list_kwargs['min_length'] = min_length
    list_kwargs.update({
        key: value for key, value in kwargs.items()
        if key in LIST_SERIALIZER_KWARGS
    })
    meta = getattr(cls, 'Meta', None)
    list_serializer_class = getattr(meta, 'list_serializer_class', ListSerializer)
    return list_serializer_class(*args, **list_kwargs)

def _get_reference(self, serializer):
    warnings.warn(
        "Method `_get_reference()` has been renamed to `get_reference()`. "
        "The old name will be removed in DRF v3.15.",
        RemovedInDRF315Warning, stacklevel=2
    )
    return self.get_reference(serializer)

def check_permissions(self, request):
    """
    Check if the request should be permitted.
    Raises an appropriate exception if the request is not permitted.
    """
    for permission in self.get_permissions():
        if not permission.has_permission(request, self):
            self.permission_denied(
                request,
                message=getattr(permission, 'message', None),
                code=getattr(permission, 'code', None)
            )

def check_object_permissions(self, request, obj):
    """
    Check if the request should be permitted for a given object.
    Raises an appropriate exception if the request is not permitted.
    """
    for permission in self.get_permissions():
        if not permission.has_object_permission(request, self, obj):
            self.permission_denied(
                request,
                message=getattr(permission, 'message', None),
                code=getattr(permission, 'code', None)
            )

def show_form_for_method(self, view, method, request, obj):
    """
    Returns True if a form should be shown for this method.
    """
    if method not in view.allowed_methods:
        return  # Not a valid method

    try:
        view.check_permissions(request)
        if obj is not None:
            view.check_object_permissions(request, obj)
    except exceptions.APIException:
        return False  # Doesn't have permissions
    return True

def get_required_permissions(self, method, model_cls):
    """
    Given a model and an HTTP method, return the list of permission
    codes that the user is required to have.
    """
    kwargs = {
        'app_label': model_cls._meta.app_label,
        'model_name': model_cls._meta.model_name
    }

    if method not in self.perms_map:
        raise exceptions.MethodNotAllowed(method)

    return [perm % kwargs for perm in self.perms_map[method]]

def _queryset(self, view):
    assert hasattr(view, 'get_queryset') \
        or getattr(view, 'queryset', None) is not None, (
        'Cannot apply {} on a view that does not set '
        '`.queryset` or have a `.get_queryset()` method.'
    ).format(self.__class__.__name__)

    if hasattr(view, 'get_queryset'):
        queryset = view.get_queryset()
        assert queryset is not None, (
            '{}.get_queryset() returned None'.format(view.__class__.__name__)
        )
        return queryset
    return view.queryset

def has_permission(self, request, view):
    # Workaround to ensure DjangoModelPermissions are not applied
    # to the root view when using DefaultRouter.
    if getattr(view, '_ignore_model_permissions', False):
        return True

    if not request.user or (
       not request.user.is_authenticated and self.authenticated_users_only):
        return False

    queryset = self._queryset(view)
    perms = self.get_required_permissions(request.method, queryset.model)

    return request.user.has_perms(perms)

def get_required_object_permissions(self, method, model_cls):
    kwargs = {
        'app_label': model_cls._meta.app_label,
        'model_name': model_cls._meta.model_name
    }

    if method not in self.perms_map:
        raise exceptions.MethodNotAllowed(method)

    return [perm % kwargs for perm in self.perms_map[method]]

def has_view_permissions(self, path, method, view):
    """
    Return `True` if the incoming request has the correct view permissions.
    """
    if view.request is None:
        return True

    try:
        view.check_permissions(view.request)
    except (exceptions.APIException, Http404, PermissionDenied):
        return False
    return True

def __init__(self):
    if not getattr(self, 'rate', None):
        self.rate = self.get_rate()
    self.num_requests, self.duration = self.parse_rate(self.rate)

def get_rate(self):
    """
    Determine the string representation of the allowed request rate.
    """
    if not getattr(self, 'scope', None):
        msg = ("You must set either `.scope` or `.rate` for '%s' throttle" %
               self.__class__.__name__)
        raise ImproperlyConfigured(msg)

    try:
        return self.THROTTLE_RATES[self.scope]
    except KeyError:
        msg = "No default throttle rate set for '%s' scope" % self.scope
        raise ImproperlyConfigured(msg)

def parse_rate(self, rate):
    """
    Given the request rate string, return a two tuple of:
    <allowed number of requests>, <period of time in seconds>
    """
    if rate is None:
        return (None, None)
    num, period = rate.split('/')
    num_requests = int(num)
    duration = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400}[period[0]]
    return (num_requests, duration)

def allow_request(self, request, view):
    """
    Implement the check to see if the request should be throttled.

    On success calls `throttle_success`.
    On failure calls `throttle_failure`.
    """
    if self.rate is None:
        return True

    self.key = self.get_cache_key(request, view)
    if self.key is None:
        return True

    self.history = self.cache.get(self.key, [])
    self.now = self.timer()

    # Drop any requests from the history which have now passed the
    # throttle duration
    while self.history and self.history[-1] <= self.now - self.duration:
        self.history.pop()
    if len(self.history) >= self.num_requests:
        return self.throttle_failure()
    return self.throttle_success()

def wait(self):
    """
    Returns the recommended next request time in seconds.
    """
    if self.history:
        remaining_duration = self.duration - (self.now - self.history[-1])
    else:
        remaining_duration = self.duration

    available_requests = self.num_requests - len(self.history) + 1
    if available_requests <= 0:
        return None

    return remaining_duration / float(available_requests)

def perform_content_negotiation(self, request, force=False):
    """
    Determine which renderer and media type to use render the response.
    """
    renderers = self.get_renderers()
    conneg = self.get_content_negotiator()

    try:
        return conneg.select_renderer(request, renderers, self.format_kwarg)
    except Exception:
        if force:
            return (renderers[0], renderers[0].media_type)
        raise

def get_format_suffix(self, **kwargs):
    """
    Determine if the request includes a '.json' style format suffix
    """
    if self.settings.FORMAT_SUFFIX_KWARG:
        return kwargs.get(self.settings.FORMAT_SUFFIX_KWARG)

def determine_version(self, request, *args, **kwargs):
    """
    If versioning is being used, then determine any API version for the
    incoming request. Returns a two-tuple of (version, versioning_scheme)
    """
    if self.versioning_class is None:
        return (None, None)
    scheme = self.versioning_class()
    return (scheme.determine_version(request, *args, **kwargs), scheme)

def name(self):
    # This ensures that we only called `__str__` lazily,
    # as in some cases calling __str__ on a model instances *might*
    # involve a database lookup.
    return str(self.obj)

def _get_fields(opts):
    fields = OrderedDict()
    for field in [field for field in opts.fields if field.serialize and not field.remote_field]:
        fields[field.name] = field

    return fields

def _merge_relationships(forward_relations, reverse_relations):
    return OrderedDict(
        list(forward_relations.items()) +
        list(reverse_relations.items())
    )

def get_pk_name(model):
    meta = model._meta.concrete_model._meta
    return _get_pk(meta).name

def __repr__(self):
    return '<%s.%s: %s %r>' % (
        self.__class__.__module__,
        self.__class__.__name__,
        self.method,
        self.get_full_path())

def to_representation(self, value):
    if value in ('', None):
        return value
    return self.choice_strings_to_values.get(str(value), value)

def __repr__(self):
    return '<%s(queryset=%s)>' % (
        self.__class__.__name__,
        smart_repr(self.queryset)
    )

def __repr__(self):
    return '<%s(queryset=%s, fields=%s)>' % (
        self.__class__.__name__,
        smart_repr(self.queryset),
        smart_repr(self.fields)
    )

def __repr__(self):
    return '<%s(queryset=%s, field=%s, date_field=%s)>' % (
        self.__class__.__name__,
        smart_repr(self.queryset),
        smart_repr(self.field),
        smart_repr(self.date_field)
    )

def __str__(self):
    ret = "%s/%s" % (self.main_type, self.sub_type)
    for key, val in self.params.items():
        ret += "; %s=%s" % (key, val)
    return ret

def __repr__(self):
    return '<%s value=%s errors=%s>' % (
        self.__class__.__name__, self.value, self.errors
    )

def manager_repr(value):
    model = value.model
    opts = model._meta
    names_and_managers = [
        (manager.name, manager)
        for manager
        in opts.managers
    ]
    for manager_name, manager_instance in names_and_managers:
        if manager_instance == value:
            return '%s.%s.all()' % (model._meta.object_name, manager_name)
    return repr(value)

def smart_repr(value):
    if isinstance(value, models.Manager):
        return manager_repr(value)

    if isinstance(value, Promise) and value._delegate_text:
        value = force_str(value)

    value = repr(value)

    # Representations like u'help text'
    # should simply be presented as 'help text'
    if value.startswith("u'") and value.endswith("'"):
        return value[1:]

    # Representations like
    # <django.core.validators.RegexValidator object at 0x1047af050>
    # Should be presented as
    # <django.core.validators.RegexValidator object>
    return re.sub(' at 0x[0-9A-Fa-f]{4,32}>', '>', value)

def field_repr(field, force_many=False):
    kwargs = field._kwargs
    if force_many:
        kwargs = kwargs.copy()
        kwargs['many'] = True
        kwargs.pop('child', None)

    arg_string = ', '.join([smart_repr(val) for val in field._args])
    kwarg_string = ', '.join([
        '%s=%s' % (key, smart_repr(val))
        for key, val in sorted(kwargs.items())
    ])
    if arg_string and kwarg_string:
        arg_string += ', '

    if force_many:
        class_name = force_many.__class__.__name__
    else:
        class_name = field.__class__.__name__

    return "%s(%s%s)" % (class_name, arg_string, kwarg_string)

def serializer_repr(serializer, indent, force_many=None):
    ret = field_repr(serializer, force_many) + ':'
    indent_str = '    ' * indent

    if force_many:
        fields = force_many.fields
    else:
        fields = serializer.fields

    for field_name, field in fields.items():
        ret += '\n' + indent_str + field_name + ' = '
        if hasattr(field, 'fields'):
            ret += serializer_repr(field, indent + 1)
        elif hasattr(field, 'child'):
            ret += list_repr(field, indent + 1)
        elif hasattr(field, 'child_relation'):
            ret += field_repr(field.child_relation, force_many=field.child_relation)
        else:
            ret += field_repr(field)

    if serializer.validators:
        ret += '\n' + indent_str + 'class Meta:'
        ret += '\n' + indent_str + '    validators = ' + smart_repr(serializer.validators)

    return ret

def list_repr(serializer, indent):
    child = serializer.child
    if hasattr(child, 'fields'):
        return serializer_repr(serializer, indent, force_many=child)
    return field_repr(serializer)

def as_string(value):
    if value is None:
        return ''
    return '%s' % value

def __new__(cls, *args, **kwargs):
    # We override this method in order to automagically create
    # `ManyRelatedField` classes instead when `many=True` is set.
    if kwargs.pop('many', False):
        return cls.many_init(*args, **kwargs)
    return super().__new__(cls, *args, **kwargs)

def many_init(cls, *args, **kwargs):
    """
    This method handles creating a parent `ManyRelatedField` instance
    when the `many=True` keyword argument is passed.

    Typically you won't need to override this method.

    Note that we're over-cautious in passing most arguments to both parent
    and child classes in order to try to cover the general case. If you're
    overriding this method you'll probably want something much simpler, eg:

    @classmethod
    def many_init(cls, *args, **kwargs):
        kwargs['child'] = cls()
        return CustomManyRelatedField(*args, **kwargs)
    """
    list_kwargs = {'child_relation': cls(*args, **kwargs)}
    for key in kwargs:
        if key in MANY_RELATION_KWARGS:
            list_kwargs[key] = kwargs[key]
    return ManyRelatedField(**list_kwargs)

def __init__(self, field, value, errors, prefix=''):
    if value is None or value == '' or not isinstance(value, Mapping):
        value = {}
    super().__init__(field, value, errors, prefix)

def run_validation(self, data=empty):
    # We force empty strings to None values for relational fields.
    if data == '':
        data = None
    return super().run_validation(data)

def get_attribute(self, instance):
    if self.use_pk_only_optimization() and self.source_attrs:
        # Optimized case, return a mock object only containing the pk attribute.
        try:
            attribute_instance = get_attribute(instance, self.source_attrs[:-1])
            value = attribute_instance.serializable_value(self.source_attrs[-1])
            if is_simple_callable(value):
                # Handle edge case where the relationship `source` argument
                # points to a `get_relationship()` method on the model.
                value = value()

            # Handle edge case where relationship `source` argument points
            # to an instance instead of a pk (e.g., a `@property`).
            value = getattr(value, 'pk', value)

            return PKOnlyObject(pk=value)
        except AttributeError:
            pass

    # Standard case, return the object instance.
    return super().get_attribute(instance)

def get_attribute(self, instance):
    # Can't have any relationships if not created
    if hasattr(instance, 'pk') and instance.pk is None:
        return []

    try:
        relationship = get_attribute(instance, self.source_attrs)
    except (KeyError, AttributeError) as exc:
        if self.default is not empty:
            return self.get_default()
        if self.allow_null:
            return None
        if not self.required:
            raise SkipField()
        msg = (
            'Got {exc_type} when attempting to get a value for field '
            '`{field}` on serializer `{serializer}`.\nThe serializer '
            'field might be named incorrectly and not match '
            'any attribute or key on the `{instance}` instance.\n'
            'Original exception text was: {exc}.'.format(
                exc_type=type(exc).__name__,
                field=self.field_name,
                serializer=self.parent.__class__.__name__,
                instance=instance.__class__.__name__,
                exc=exc
            )
        )
        raise type(exc)(msg)

    return relationship.all() if hasattr(relationship, 'all') else relationship

def get_attribute(instance, attrs):
    """
    Similar to Python's built in `getattr(instance, attr)`,
    but takes a list of nested attributes, instead of a single attribute.

    Also accepts either attribute lookup on objects or dictionary lookups.
    """
    for attr in attrs:
        try:
            if isinstance(instance, Mapping):
                instance = instance[attr]
            else:
                instance = getattr(instance, attr)
        except ObjectDoesNotExist:
            return None
        if is_simple_callable(instance):
            try:
                instance = instance()
            except (AttributeError, KeyError) as exc:
                # If we raised an Attribute or KeyError here it'd get treated
                # as an omitted field in `Field.get_attribute()`. Instead we
                # raise a ValueError to ensure the exception is not masked.
                raise ValueError('Exception raised in callable attribute "{}"; original exception was: {}'.format(attr, exc))

    return instance

def get_attribute(self, instance):
    """
    Given the *outgoing* object instance, return the primitive value
    that should be used for this field.
    """
    try:
        return get_attribute(instance, self.source_attrs)
    except BuiltinSignatureError as exc:
        msg = (
            'Field source for `{serializer}.{field}` maps to a built-in '
            'function type and is invalid. Define a property or method on '
            'the `{instance}` instance that wraps the call to the built-in '
            'function.'.format(
                serializer=self.parent.__class__.__name__,
                field=self.field_name,
                instance=instance.__class__.__name__,
            )
        )
        raise type(exc)(msg)
    except (KeyError, AttributeError) as exc:
        if self.default is not empty:
            return self.get_default()
        if self.allow_null:
            return None
        if not self.required:
            raise SkipField()
        msg = (
            'Got {exc_type} when attempting to get a value for field '
            '`{field}` on serializer `{serializer}`.\nThe serializer '
            'field might be named incorrectly and not match '
            'any attribute or key on the `{instance}` instance.\n'
            'Original exception text was: {exc}.'.format(
                exc_type=type(exc).__name__,
                field=self.field_name,
                serializer=self.parent.__class__.__name__,
                instance=instance.__class__.__name__,
                exc=exc
            )
        )
        raise type(exc)(msg)

def __getitem__(self, key):
    if hasattr(key, '_proxy_class'):
        # Deal with proxy classes. Ie. BoundField behaves as if it
        # is a Field instance when using ClassLookupDict.
        base_class = key._proxy_class
    else:
        base_class = key.__class__

    for cls in inspect.getmro(base_class):
        if cls in self.mapping:
            return self.mapping[cls]
    raise KeyError('Class %s not found in lookup.' % base_class.__name__)

def get_choices(self, cutoff=None):
    queryset = self.get_queryset()
    if queryset is None:
        # Ensure that field.choices returns something sensible
        # even when accessed with a read-only field.
        return {}

    if cutoff is not None:
        queryset = queryset[:cutoff]

    return OrderedDict([
        (
            self.to_representation(item),
            self.display_value(item)
        )
        for item in queryset
    ])

def to_representation(self, value):
    """
    Transform the *outgoing* native value into primitive data.
    """
    raise NotImplementedError(
        '{cls}.to_representation() must be implemented for field {field_name}.'.format(
            cls=self.__class__.__name__,
            field_name=self.field_name,
        )
    )

def iter_options(self):

    class StartOptionGroup:
        start_option_group = True
        end_option_group = False

        def __init__(self, label):
            self.label = label

    class EndOptionGroup:
        start_option_group = False
        end_option_group = True

    class Option:
        start_option_group = False
        end_option_group = False

        def __init__(self, value, display_text, disabled=False):
            self.value = value
            self.display_text = display_text
            self.disabled = disabled

    count = 0

    for key, value in self.iter_options():
        if cutoff and count >= cutoff:
            break

        if isinstance(value, dict):
            yield StartOptionGroup(label=key)
            for sub_key, sub_value in value.items():
                if cutoff and count >= cutoff:
                    break
                yield Option(value=sub_key, display_text=sub_value)
                count += 1
            yield EndOptionGroup()
        else:
            yield Option(value=key, display_text=value)
            count += 1

    if cutoff and count >= cutoff and cutoff_text:
        cutoff_text = cutoff_text.format(count=cutoff)
        yield Option(value='n/a', display_text=cutoff_text, disabled=True)

def __init__(self, force_user, force_token):
    self.force_user = force_user
    self.force_token = force_token

def __init__(self, format=empty, input_formats=None, **kwargs):
    if format is not empty:
        self.format = format
    if input_formats is not None:
        self.input_formats = input_formats
    super().__init__(**kwargs)

def __init__(self, format=empty, input_formats=None, **kwargs):
    if format is not empty:
        self.format = format
    if input_formats is not None:
        self.input_formats = input_formats
    super().__init__(**kwargs)

def __init__(self, operator_class, op1_class):
    self.operator_class = operator_class
    self.op1_class = op1_class

def _readable_fields(self):
    for field in self.fields.values():
        if not field.write_only:
            yield field

def to_internal_value(self, data):
    if self.pk_field is not None:
        data = self.pk_field.to_internal_value(data)
    queryset = self.get_queryset()
    try:
        if isinstance(data, bool):
            raise TypeError
        return queryset.get(pk=data)
