def to_choices_dict(choices):
    """
    Convert choices into key/value dicts.

    to_choices_dict([1]) -> {1: 1}
    to_choices_dict([(1, '1st'), (2, '2nd')]) -> {1: '1st', 2: '2nd'}
    to_choices_dict([('Group', ((1, '1st'), 2))]) -> {'Group': {1: '1st', 2: '2'}}
    """
    # Allow single, paired or grouped choices style:
    # choices = [1, 2, 3]
    # choices = [(1, 'First'), (2, 'Second'), (3, 'Third')]
    # choices = [('Category', ((1, 'First'), (2, 'Second'))), (3, 'Third')]
    ret = OrderedDict()
    for choice in choices:
        if not isinstance(choice, (list, tuple)):
            # single choice
            ret[choice] = choice
        else:
            key, value = choice
            if isinstance(value, (list, tuple)):
                # grouped choices (category, sub choices)
                ret[key] = to_choices_dict(value)
            else:
                # paired choice (key, display value)
                ret[key] = value
    return ret

def flatten_choices_dict(choices):
    """
    Convert a group choices dict into a flat dict of choices.

    flatten_choices_dict({1: '1st', 2: '2nd'}) -> {1: '1st', 2: '2nd'}
    flatten_choices_dict({'Group': {1: '1st', 2: '2nd'}}) -> {1: '1st', 2: '2nd'}
    """
    ret = OrderedDict()
    for key, value in choices.items():
        if isinstance(value, dict):
            # grouped choices (category, sub choices)
            for sub_key, sub_value in value.items():
                ret[sub_key] = sub_value
        else:
            # choice (key, display value)
            ret[key] = value
    return ret

def _set_choices(self, choices):
    self.grouped_choices = to_choices_dict(choices)
    self._choices = flatten_choices_dict(self.grouped_choices)

    # Map the string representation of choices to the underlying value.
    # Allows us to deal with eg. integer choices while supporting either
    # integer or string input, but still get the correct datatype out.
    self.choice_strings_to_values = {
        str(key): key for key in self.choices
    }

def get_error_detail(exc_info):
    """
    Given a Django ValidationError, return a list of ErrorDetail,
    with the `code` populated.
    """
    code = getattr(exc_info, 'code', None) or 'invalid'

    try:
        error_dict = exc_info.error_dict
    except AttributeError:
        return [
            ErrorDetail((error.message % error.params) if error.params else error.message,
                        code=error.code if error.code else code)
            for error in exc_info.error_list]
    return {
        k: [
            ErrorDetail((error.message % error.params) if error.params else error.message,
                        code=error.code if error.code else code)
            for error in errors
        ] for k, errors in error_dict.items()
    }

def _get_error_details(data, default_code=None):
    """
    Descend into a nested data structure, forcing any
    lazy translation strings or strings into `ErrorDetail`.
    """
    from rest_framework.utils.serializer_helpers import ReturnDict
    from rest_framework.utils.serializer_helpers import ReturnList
    if isinstance(data, (list, tuple)):
        ret = [
            _get_error_details(item, default_code) for item in data
        ]
        if isinstance(data, ReturnList):
            return ReturnList(ret, serializer=data.serializer)
        return ret
    elif isinstance(data, dict):
        ret = {
            key: _get_error_details(value, default_code)
            for key, value in data.items()
        }
        if isinstance(data, ReturnDict):
            return ReturnDict(ret, serializer=data.serializer)
        return ret

    text = force_str(data)
    code = getattr(data, 'code', default_code)
    return ErrorDetail(text, code)

def __repr__(self):
    return 'ErrorDetail(string=%r, code=%r)' % (
        str(self),
        self.code,
    )

def __init__(self, detail=None, code=None):
    if detail is None:
        detail = self.default_detail
    if code is None:
        code = self.default_code

    self.detail = _get_error_details(detail, code)

def get_codes(self):
    """
    Return only the code part of the error details.

    Eg. {"name": ["required"]}
    """
    return _get_codes(self.detail)

def get_full_details(self):
    """
    Return both the message & code parts of the error details.

    Eg. {"name": [{"message": "This field is required.", "code": "required"}]}
    """
    return _get_full_details(self.detail)

def __init__(self, detail=None, code=None):
    if detail is None:
        detail = self.default_detail
    if code is None:
        code = self.default_code

    # For validation failures, we may collect many errors together,
    # so the details should always be coerced to a list if not already.
    if isinstance(detail, tuple):
        detail = list(detail)
    elif not isinstance(detail, dict) and not isinstance(detail, list):
        detail = [detail]

    self.detail = _get_error_details(detail, code)

def errors(self):
    if not hasattr(self, '_errors'):
        msg = 'You must call `.is_valid()` before accessing `.errors`.'
        raise AssertionError(msg)
    return self._errors

def as_serializer_error(exc):
    assert isinstance(exc, (ValidationError, DjangoValidationError))

    if isinstance(exc, DjangoValidationError):
        detail = get_error_detail(exc)
    else:
        detail = exc.detail

    if isinstance(detail, Mapping):
        # If errors may be a dict we use the standard {key: list of values}.
        # Here we ensure that all the values are *lists* of errors.
        return {
            key: value if isinstance(value, (list, Mapping)) else [value]
            for key, value in detail.items()
        }
    elif isinstance(detail, list):
        # Errors raised as a list are non-field errors.
        return {
            api_settings.NON_FIELD_ERRORS_KEY: detail
        }
    # Errors raised as a string are non-field errors.
    return {
        api_settings.NON_FIELD_ERRORS_KEY: [detail]
    }

def errors(self):
    ret = super().errors
    if isinstance(ret, list) and len(ret) == 1 and getattr(ret[0], 'code', None) == 'null':
        # Edge case. Provide a more descriptive error than
        # "this field may not be null", when no data is passed.
        detail = ErrorDetail('No data provided', code='null')
        ret = {api_settings.NON_FIELD_ERRORS_KEY: [detail]}
    if isinstance(ret, dict):
        return ReturnDict(ret, serializer=self)
    return ReturnList(ret, serializer=self)

def __str__(self):
    if self.result is None:
        self.result = self.format_string.format(*self.args, **self.kwargs)
        self.format_string, self.args, self.kwargs = None, None, None
    return self.result

def validators(self):
    if not hasattr(self, '_validators'):
        self._validators = self.get_validators()
    return self._validators

def __init__(self, allow_unicode=False, **kwargs):
    super().__init__(**kwargs)
    self.allow_unicode = allow_unicode
    if self.allow_unicode:
        validator = RegexValidator(re.compile(r'^[-\w]+\Z', re.UNICODE), message=self.error_messages['invalid_unicode'])
    else:
        validator = RegexValidator(re.compile(r'^[-a-zA-Z0-9_]+$'), message=self.error_messages['invalid'])
    self.validators.append(validator)

def get_validators(self):
    """
    Determine the set of validators to use when instantiating serializer.
    """
    # If the validators have been declared explicitly then use that.
    validators = getattr(getattr(self, 'Meta', None), 'validators', None)
    if validators is not None:
        return list(validators)

    # Otherwise use the default set of validators.
    return (
        self.get_unique_together_validators() +
        self.get_unique_for_date_validators()
    )

def to_internal_value(self, data):
    """
    List of dicts of native values <- List of dicts of primitive datatypes.
    """
    if html.is_html_input(data):
        data = html.parse_html_list(data, default=[])
    if isinstance(data, (str, Mapping)) or not hasattr(data, '__iter__'):
        self.fail('not_a_list', input_type=type(data).__name__)
    if not self.allow_empty and len(data) == 0:
        self.fail('empty')
    return self.run_child_validation(data)

def run_child_validation(self, data):
    result = []
    errors = OrderedDict()

    for idx, item in enumerate(data):
        try:
            result.append(self.child.run_validation(item))
        except ValidationError as e:
            errors[idx] = e.detail

    if not errors:
        return result
    raise ValidationError(errors)

def to_internal_value(self, data):
    """
    Dicts of native values <- Dicts of primitive datatypes.
    """
    if html.is_html_input(data):
        data = html.parse_html_dict(data)
    if not isinstance(data, dict):
        self.fail('not_a_dict', input_type=type(data).__name__)
    if not self.allow_empty and len(data) == 0:
        self.fail('empty')

    return self.run_child_validation(data)

def run_child_validation(self, data):
    result = {}
    errors = OrderedDict()

    for key, value in data.items():
        key = str(key)

        try:
            result[key] = self.child.run_validation(value)
        except ValidationError as e:
            errors[key] = e.detail

    if not errors:
        return result
    raise ValidationError(errors)

def get_initial(self):
    """
    Return a value to use when the field is being returned as a primitive
    value, without any object instance.
    """
    if callable(self.initial):
        return self.initial()
    return self.initial

def data(self):
    if hasattr(self, 'initial_data') and not hasattr(self, '_validated_data'):
        msg = (
            'When a serializer is passed a `data` keyword argument you '
            'must call `.is_valid()` before attempting to access the '
            'serialized `.data` representation.\n'
            'You should either call `.is_valid()` first, '
            'or access `.initial_data` instead.'
        )
        raise AssertionError(msg)

    if not hasattr(self, '_data'):
        if self.instance is not None and not getattr(self, '_errors', None):
            self._data = self.to_representation(self.instance)
        elif hasattr(self, '_validated_data') and not getattr(self, '_errors', None):
            self._data = self.to_representation(self.validated_data)
        else:
            self._data = self.get_initial()
    return self._data

def validated_data(self):
    if not hasattr(self, '_validated_data'):
        msg = 'You must call `.is_valid()` before accessing `.validated_data`.'
        raise AssertionError(msg)
    return self._validated_data

def __deepcopy__(self, memo):
    """
    When cloning fields we instantiate using the arguments it was
    originally created with, rather than copying the complete state.
    """
    # Treat regexes and validators as immutable.
    # See https://github.com/encode/django-rest-framework/issues/1954
    # and https://github.com/encode/django-rest-framework/pull/4489
    args = [
        copy.deepcopy(item) if not isinstance(item, REGEX_TYPE) else item
        for item in self._args
    ]
    kwargs = {
        key: (copy.deepcopy(value, memo) if (key not in ('validators', 'regex')) else value)
        for key, value in self._kwargs.items()
    }
    return self.__class__(*args, **kwargs)

def __init__(self):
    assert coreapi, 'Using CoreAPIOpenAPIRenderer, but `coreapi` is not installed.'
    assert yaml, 'Using CoreAPIOpenAPIRenderer, but `pyyaml` is not installed.'

def is_enabled():
    """Is CoreAPI Mode enabled?"""
    return issubclass(api_settings.DEFAULT_SCHEMA_CLASS, AutoSchema)

def to_representation(self, value):
    coerce_to_string = getattr(self, 'coerce_to_string', api_settings.COERCE_DECIMAL_TO_STRING)

    if value is None:
        if coerce_to_string:
            return ''
        else:
            return None

    if not isinstance(value, decimal.Decimal):
        value = decimal.Decimal(str(value).strip())

    quantized = self.quantize(value)

    if not coerce_to_string:
        return quantized
    if self.localize:
        return localize_input(quantized)

    return '{:f}'.format(quantized)

def quantize(self, value):
    """
    Quantize the decimal value to the configured precision.
    """
    if self.decimal_places is None:
        return value

    context = decimal.getcontext().copy()
    if self.max_digits is not None:
        context.prec = self.max_digits
    return value.quantize(
        decimal.Decimal('.1') ** self.decimal_places,
        rounding=self.rounding,
        context=context
    )

def enforce_timezone(self, value):
    """
    When `self.default_timezone` is `None`, always return naive datetimes.
    When `self.default_timezone` is not `None`, always return aware datetimes.
    """
    field_timezone = self.timezone if hasattr(self, 'timezone') else self.default_timezone()

    if field_timezone is not None:
        if timezone.is_aware(value):
            try:
                return value.astimezone(field_timezone)
            except OverflowError:
                self.fail('overflow')
        try:
            return timezone.make_aware(value, field_timezone)
        except InvalidTimeError:
            self.fail('make_aware', timezone=field_timezone)
    elif (field_timezone is None) and timezone.is_aware(value):
        return timezone.make_naive(value, datetime.timezone.utc)
    return value

def to_representation(self, value):
    if not value:
        return None

    output_format = getattr(self, 'format', api_settings.DATETIME_FORMAT)

    if output_format is None or isinstance(value, str):
        return value

    value = self.enforce_timezone(value)

    if output_format.lower() == ISO_8601:
        value = value.isoformat()
        if value.endswith('+00:00'):
            value = value[:-6] + 'Z'
        return value
    return value.strftime(output_format)

def to_internal_value(self, data):
    if isinstance(data, str) or not hasattr(data, '__iter__'):
        self.fail('not_a_list', input_type=type(data).__name__)
    if not self.allow_empty and len(data) == 0:
        self.fail('empty')

    return {
        # Arguments for super() are needed because of scoping inside
        # comprehensions.
        super(MultipleChoiceField, self).to_internal_value(item)
        for item in data
    }

def __call__(self, value):
    for surrogate_character in (ch for ch in str(value)
                                if 0xD800 <= ord(ch) <= 0xDFFF):
        message = self.message.format(code_point=ord(surrogate_character))
        raise ValidationError(message, code=self.code)

def coerce_path(self, path, method, view):
    """
    Coerce {pk} path arguments into the name of the model field,
    where possible. This is cleaner for an external representation.
    (Ie. "this is an identifier", not "this is a database primary key")
    """
    if not self.coerce_path_pk or '{pk}' not in path:
        return path
    model = getattr(getattr(view, 'queryset', None), 'model', None)
    if model:
        field_name = get_pk_name(model)
    else:
        field_name = 'id'
    return path.replace('{pk}', '{%s}' % field_name)

def to_internal_value(self, data):
    try:
        if self.binary or getattr(data, 'is_json_string', False):
            if isinstance(data, bytes):
                data = data.decode()
            return json.loads(data, cls=self.decoder)
        else:
            json.dumps(data, cls=self.encoder)
    except (TypeError, ValueError):
        self.fail('invalid')
    return data

def parse(self, stream, media_type=None, parser_context=None):
    """
    Parses the incoming bytestream as JSON and returns the resulting data.
    """
    from rest_framework.utils import json
    parser_context = parser_context or {}
    encoding = parser_context.get('encoding', settings.DEFAULT_CHARSET)

    try:
        decoded_stream = codecs.getreader(encoding)(stream)
        parse_constant = json.strict_constant if self.strict else None
        return json.load(decoded_stream, parse_constant=parse_constant)
    except ValueError as exc:
        raise ParseError('JSON parse error - %s' % str(exc))

def parse(self, stream, media_type=None, parser_context=None):
    """
    Parses the incoming bytestream as a URL encoded form,
    and returns the resulting QueryDict.
    """
    parser_context = parser_context or {}
    encoding = parser_context.get('encoding', settings.DEFAULT_CHARSET)
    return QueryDict(stream.read(), encoding=encoding)

def get_filename(self, stream, media_type, parser_context):
    """
    Detects the uploaded file name. First searches a 'filename' url kwarg.
    Then tries to parse Content-Disposition header.
    """
    from rest_framework.compat import parse_header_parameters
    try:
        return parser_context['kwargs']['filename']
    except KeyError:
        pass

    try:
        meta = parser_context['request'].META
        disposition, params = parse_header_parameters(meta['HTTP_CONTENT_DISPOSITION'])
        if 'filename*' in params:
            return params['filename*']
        else:
            return params['filename']
    except (AttributeError, KeyError, ValueError):
        pass

def _get_full_details(detail):
    if isinstance(detail, list):
        return [_get_full_details(item) for item in detail]
    elif isinstance(detail, dict):
        return {key: _get_full_details(value) for key, value in detail.items()}
    return {
        'message': detail,
        'code': detail.code
    }

def get_indent(self, accepted_media_type, renderer_context):
    if accepted_media_type:
        # If the media type looks like 'application/json; indent=4',
        # then pretty print the result.
        # Note that we coerce `indent=0` into `indent=None`.
        base_media_type, params = parse_header_parameters(accepted_media_type)
        try:
            return zero_as_none(max(min(int(params['indent']), 8), 0))
        except (KeyError, ValueError, TypeError):
            pass

    # If 'indent' is provided in the context, then pretty print the result.
    # E.g. If we're being called by the BrowsableAPIRenderer.
    return renderer_context.get('indent', None)

def render_field(self, field, parent_style):
    if isinstance(field._field, serializers.HiddenField):
        return ''

    style = self.default_style[field].copy()
    style.update(field.style)
    if 'template_pack' not in style:
        style['template_pack'] = parent_style.get('template_pack', self.template_pack)
    style['renderer'] = self

    # Get a clone of the field with text-only value representation.
    field = field.as_form_field()

    if style.get('input_type') == 'datetime-local' and isinstance(field.value, str):
        field.value = field.value.rstrip('Z')

    if 'template' in style:
        template_name = style['template']
    else:
        template_name = style['template_pack'].strip('/') + '/' + style['base_template']

    template = loader.get_template(template_name)
    context = {'field': field, 'style': style}
    return template.render(context)

def render(self, data, accepted_media_type=None, renderer_context=None):
    codec = coreapi.codecs.CoreJSONCodec()
    schema = base64.b64encode(codec.encode(data)).decode('ascii')

    template = loader.get_template(self.template)
    context = {'schema': mark_safe(schema)}
    request = renderer_context['request']
    return template.render(context, request=request)

def render(self, data, media_type=None, renderer_context=None):
    indent = bool(renderer_context.get('indent', 0))
    codec = coreapi.codecs.CoreJSONCodec()
    return codec.dump(data, indent=indent)

def render_field(field, style):
    renderer = style.get('renderer', HTMLFormRenderer())
    return renderer.render_field(field, style)

def get_default_renderer(self, view):
    """
    Return an instance of the first valid renderer.
    (Don't use another documenting renderer.)
    """
    renderers = [renderer for renderer in view.renderer_classes
                 if not issubclass(renderer, BrowsableAPIRenderer)]
    non_template_renderers = [renderer for renderer in renderers
                              if not hasattr(renderer, 'get_template_names')]

    if not renderers:
        return None
    elif non_template_renderers:
        return non_template_renderers[0]()
    return renderers[0]()

def get_rendered_html_form(self, data, view, method, request):
    """
    Return a string representing a rendered HTML form, possibly bound to
    either the input or output data.

    In the absence of the View having an associated form then return None.
    """
    # See issue #2089 for refactoring this.
    serializer = getattr(data, 'serializer', None)
    if serializer and not getattr(serializer, 'many', False):
        instance = getattr(serializer, 'instance', None)
        if isinstance(instance, Page):
            instance = None
    else:
        instance = None

    # If this is valid serializer data, and the form is for the same
    # HTTP method as was used in the request then use the existing
    # serializer instance, rather than dynamically creating a new one.
    if request.method == method and serializer is not None:
        try:
            kwargs = {'data': request.data}
        except ParseError:
            kwargs = {}
        existing_serializer = serializer
    else:
        kwargs = {}
        existing_serializer = None

    with override_method(view, request, method) as request:
        if not self.show_form_for_method(view, method, request, instance):
            return

        if method in ('DELETE', 'OPTIONS'):
            return True  # Don't actually need to return a form

        has_serializer = getattr(view, 'get_serializer', None)
        has_serializer_class = getattr(view, 'serializer_class', None)

        if (
            (not has_serializer and not has_serializer_class) or
            not any(is_form_media_type(parser.media_type) for parser in view.parser_classes)
        ):
            return

        if existing_serializer is not None:
            try:
                return self.render_form_for_serializer(existing_serializer)
            except TypeError:
                pass

        if has_serializer:
            if method in ('PUT', 'PATCH'):
                serializer = view.get_serializer(instance=instance, **kwargs)
            else:
                serializer = view.get_serializer(**kwargs)
        else:
            # at this point we must have a serializer_class
            if method in ('PUT', 'PATCH'):
                serializer = self._get_serializer(view.serializer_class, view,
                                                  request, instance=instance, **kwargs)
            else:
                serializer = self._get_serializer(view.serializer_class, view,
                                                  request, **kwargs)

        return self.render_form_for_serializer(serializer)

def get_filter_form(self, data, view, request):
    if not hasattr(view, 'get_queryset') or not hasattr(view, 'filter_backends'):
        return

    # Infer if this is a list view or not.
    paginator = getattr(view, 'paginator', None)
    if isinstance(data, list):
        pass
    elif paginator is not None and data is not None:
        try:
            paginator.get_results(data)
        except (TypeError, KeyError):
            return
    elif not isinstance(data, list):
        return

    queryset = view.get_queryset()
    elements = []
    for backend in view.filter_backends:
        if hasattr(backend, 'to_html'):
            html = backend().to_html(request, queryset, view)
            if html:
                elements.append(html)

    if not elements:
        return

    template = loader.get_template(self.filter_template)
    context = {'elements': elements}
    return template.render(context)

def get_context(self, data, accepted_media_type, renderer_context):
    """
    Render the HTML for the browsable API representation.
    """
    context = super().get_context(
        data, accepted_media_type, renderer_context
    )

    paginator = getattr(context['view'], 'paginator', None)
    if paginator is not None and data is not None:
        try:
            results = paginator.get_results(data)
        except (TypeError, KeyError):
            results = data
    else:
        results = data

    if results is None:
        header = {}
        style = 'detail'
    elif isinstance(results, list):
        header = results[0] if results else {}
        style = 'list'
    else:
        header = results
        style = 'detail'

    columns = [key for key in header if key != 'url']
    details = [key for key in header if key != 'url']

    if isinstance(results, list) and 'view' in renderer_context:
        for result in results:
            url = self.get_result_url(result, context['view'])
            if url is not None:
                result.setdefault('url', url)

    context['style'] = style
    context['columns'] = columns
    context['details'] = details
    context['results'] = results
    context['error_form'] = getattr(self, 'error_form', None)
    context['error_title'] = getattr(self, 'error_title', None)
    return context

def render(self, data, accepted_media_type=None, renderer_context=None):
    from django.test.client import encode_multipart

    if hasattr(data, 'items'):
        for key, value in data.items():
            assert not isinstance(value, dict), (
                "Test data contained a dictionary value for key '%s', "
                "but multipart uploads do not support nested data. "
                "You may want to consider using format='json' in this "
                "test case." % key
            )
    return encode_multipart(self.BOUNDARY, data)

def render(self, data, media_type=None, renderer_context=None):
    # disable yaml advanced feature 'alias' for clean, portable, and readable output
    class Dumper(yaml.Dumper):
        def ignore_aliases(self, data):
            return True
    return yaml.dump(data, default_flow_style=False, sort_keys=False, Dumper=Dumper).encode('utf-8')

def get_schema(self, instance):
    CLASS_TO_TYPENAME = {
        coreschema.Object: 'object',
        coreschema.Array: 'array',
        coreschema.Number: 'number',
        coreschema.Integer: 'integer',
        coreschema.String: 'string',
        coreschema.Boolean: 'boolean',
    }

    schema = {}
    if instance.__class__ in CLASS_TO_TYPENAME:
        schema['type'] = CLASS_TO_TYPENAME[instance.__class__]
    schema['title'] = instance.title
    schema['description'] = instance.description
    if hasattr(instance, 'enum'):
        schema['enum'] = instance.enum
    return schema

def get_parameters(self, link):
    parameters = []
    for field in link.fields:
        if field.location not in ['path', 'query']:
            continue
        parameter = {
            'name': field.name,
            'in': field.location,
        }
        if field.required:
            parameter['required'] = True
        if field.description:
            parameter['description'] = field.description
        if field.schema:
            parameter['schema'] = self.get_schema(field.schema)
        parameters.append(parameter)
    return parameters

def get_operation(self, link, name, tag):
    operation_id = "%s_%s" % (tag, name) if tag else name
    parameters = self.get_parameters(link)

    operation = {
        'operationId': operation_id,
    }
    if link.title:
        operation['summary'] = link.title
    if link.description:
        operation['description'] = link.description
    if parameters:
        operation['parameters'] = parameters
    if tag:
        operation['tags'] = [tag]
    return operation

def get_paths(self, document):
    paths = {}

    tag = None
    for name, link in document.links.items():
        path = parse.urlparse(link.url).path
        method = link.action.lower()
        paths.setdefault(path, {})
        paths[path][method] = self.get_operation(link, name, tag=tag)

    for tag, section in document.data.items():
        for name, link in section.links.items():
            path = parse.urlparse(link.url).path
            method = link.action.lower()
            paths.setdefault(path, {})
            paths[path][method] = self.get_operation(link, name, tag=tag)

    return paths

def get_structure(self, data):
    return {
        'openapi': '3.0.0',
        'info': {
            'version': '',
            'title': data.title,
            'description': data.description
        },
        'servers': [{
            'url': data.url
        }],
        'paths': self.get_paths(data)
    }

def render(self, data, media_type=None, renderer_context=None):
    structure = self.get_structure(data)
    return yaml.dump(structure, default_flow_style=False).encode()

def render(self, data, media_type=None, renderer_context=None):
    structure = self.get_structure(data)
    return json.dumps(
        structure, indent=4,
        ensure_ascii=self.ensure_ascii).encode('utf-8')

def get_next_link(self):
    if not self.page.has_next():
        return None
    url = self.request.build_absolute_uri()
    page_number = self.page.next_page_number()
    return replace_query_param(url, self.page_query_param, page_number)

def get_previous_link(self):
    if not self.page.has_previous():
        return None
    url = self.request.build_absolute_uri()
    page_number = self.page.previous_page_number()
    if page_number == 1:
        return remove_query_param(url, self.page_query_param)
    return replace_query_param(url, self.page_query_param, page_number)

def get_html_context(self):
    base_url = self.request.build_absolute_uri()

    def page_number_to_url(page_number):
        if page_number == 1:
            return remove_query_param(base_url, self.page_query_param)
        else:
            return replace_query_param(base_url, self.page_query_param, page_number)

    current = self.page.number
    final = self.page.paginator.num_pages
    page_numbers = _get_displayed_page_numbers(current, final)
    page_links = _get_page_links(page_numbers, current, page_number_to_url)

    return {
        'previous_url': self.get_previous_link(),
        'next_url': self.get_next_link(),
        'page_links': page_links
    }

def to_html(self):
    template = loader.get_template(self.template)
    context = self.get_html_context()
    return template.render(context)

def get_next_link(self):
    if self.offset + self.limit >= self.count:
        return None

    url = self.request.build_absolute_uri()
    url = replace_query_param(url, self.limit_query_param, self.limit)

    offset = self.offset + self.limit
    return replace_query_param(url, self.offset_query_param, offset)

def get_previous_link(self):
    if self.offset <= 0:
        return None

    url = self.request.build_absolute_uri()
    url = replace_query_param(url, self.limit_query_param, self.limit)

    if self.offset - self.limit <= 0:
        return remove_query_param(url, self.offset_query_param)

    offset = self.offset - self.limit
    return replace_query_param(url, self.offset_query_param, offset)

def get_html_context(self):
    base_url = self.request.build_absolute_uri()

    if self.limit:
        current = _divide_with_ceil(self.offset, self.limit) + 1

        # The number of pages is a little bit fiddly.
        # We need to sum both the number of pages from current offset to end
        # plus the number of pages up to the current offset.
        # When offset is not strictly divisible by the limit then we may
        # end up introducing an extra page as an artifact.
        final = (
            _divide_with_ceil(self.count - self.offset, self.limit) +
            _divide_with_ceil(self.offset, self.limit)
        )

        final = max(final, 1)
    else:
        current = 1
        final = 1

    if current > final:
        current = final

    def page_number_to_url(page_number):
        if page_number == 1:
            return remove_query_param(base_url, self.offset_query_param)
        else:
            offset = self.offset + ((page_number - current) * self.limit)
            return replace_query_param(base_url, self.offset_query_param, offset)

    page_numbers = _get_displayed_page_numbers(current, final)
    page_links = _get_page_links(page_numbers, current, page_number_to_url)

    return {
        'previous_url': self.get_previous_link(),
        'next_url': self.get_next_link(),
        'page_links': page_links
    }

def to_html(self):
    template = loader.get_template(self.template)
    context = self.get_html_context()
    return template.render(context)

def page_number_to_url(page_number):
    if page_number == 1:
        return remove_query_param(base_url, self.page_query_param)
    else:
        return replace_query_param(base_url, self.page_query_param, page_number)

def page_number_to_url(page_number):
    if page_number == 1:
        return remove_query_param(base_url, self.offset_query_param)
    else:
        offset = self.offset + ((page_number - current) * self.limit)
        return replace_query_param(base_url, self.offset_query_param, offset)

def _reverse_ordering(ordering_tuple):
    """
    Given an order_by tuple such as `('-created', 'uuid')` reverse the
    ordering and return a new tuple, eg. `('created', '-uuid')`.
    """
    def invert(x):
        return x[1:] if x.startswith('-') else '-' + x

    return tuple([invert(item) for item in ordering_tuple])

def paginate_queryset(self, queryset, request, view=None):
    self.page_size = self.get_page_size(request)
    if not self.page_size:
        return None

    self.base_url = request.build_absolute_uri()
    self.ordering = self.get_ordering(request, queryset, view)

    self.cursor = self.decode_cursor(request)
    if self.cursor is None:
        (offset, reverse, current_position) = (0, False, None)
    else:
        (offset, reverse, current_position) = self.cursor

    # Cursor pagination always enforces an ordering.
    if reverse:
        queryset = queryset.order_by(*_reverse_ordering(self.ordering))
    else:
        queryset = queryset.order_by(*self.ordering)

    # If we have a cursor with a fixed position then filter by that.
    if current_position is not None:
        order = self.ordering[0]
        is_reversed = order.startswith('-')
        order_attr = order.lstrip('-')

        # Test for: (cursor reversed) XOR (queryset reversed)
        if self.cursor.reverse != is_reversed:
            kwargs = {order_attr + '__lt': current_position}
        else:
            kwargs = {order_attr + '__gt': current_position}

        queryset = queryset.filter(**kwargs)

    # If we have an offset cursor then offset the entire page by that amount.
    # We also always fetch an extra item in order to determine if there is a
    # page following on from this one.
    results = list(queryset[offset:offset + self.page_size + 1])
    self.page = list(results[:self.page_size])

    # Determine the position of the final item following the page.
    if len(results) > len(self.page):
        has_following_position = True
        following_position = self._get_position_from_instance(results[-1], self.ordering)
    else:
        has_following_position = False
        following_position = None

    if reverse:
        # If we have a reverse queryset, then the query ordering was in reverse
        # so we need to reverse the items again before returning them to the user.
        self.page = list(reversed(self.page))

        # Determine next and previous positions for reverse cursors.
        self.has_next = (current_position is not None) or (offset > 0)
        self.has_previous = has_following_position
        if self.has_next:
            self.next_position = current_position
        if self.has_previous:
            self.previous_position = following_position
    else:
        # Determine next and previous positions for forward cursors.
        self.has_next = has_following_position
        self.has_previous = (current_position is not None) or (offset > 0)
        if self.has_next:
            self.next_position = following_position
        if self.has_previous:
            self.previous_position = current_position

    # Display page controls in the browsable API if there is more
    # than one page.
    if (self.has_previous or self.has_next) and self.template is not None:
        self.display_page_controls = True

    return self.page

def get_ordering(self, request, queryset, view):
    """
    Return a tuple of strings, that may be used in an `order_by` method.
    """
    ordering_filters = [
        filter_cls for filter_cls in getattr(view, 'filter_backends', [])
        if hasattr(filter_cls, 'get_ordering')
    ]

    if ordering_filters:
        # If a filter exists on the view that implements `get_ordering`
        # then we defer to that filter to determine the ordering.
        filter_cls = ordering_filters[0]
        filter_instance = filter_cls()
        ordering = filter_instance.get_ordering(request, queryset, view)
        assert ordering is not None, (
            'Using cursor pagination, but filter class {filter_cls} '
            'returned a `None` ordering.'.format(
                filter_cls=filter_cls.__name__
            )
        )
    else:
        # The default case is to check for an `ordering` attribute
        # on this pagination instance.
        ordering = self.ordering
        assert ordering is not None, (
            'Using cursor pagination, but no ordering attribute was declared '
            'on the pagination class.'
        )
        assert '__' not in ordering, (
            'Cursor pagination does not support double underscore lookups '
            'for orderings. Orderings should be an unchanging, unique or '
            'nearly-unique field on the model, such as "-created" or "pk".'
        )

    assert isinstance(ordering, (str, list, tuple)), (
        'Invalid ordering. Expected string or tuple, but got {type}'.format(
            type=type(ordering).__name__
        )
    )

    if isinstance(ordering, str):
        return (ordering,)
    return tuple(ordering)

def add_class(value, css_class):
    """
    https://stackoverflow.com/questions/4124220/django-adding-css-classes-when-rendering-form-fields-in-a-template

    Inserts classes into template variables that contain HTML tags,
    useful for modifying forms without needing to change the Form objects.

    Usage:

        {{ field.label_tag|add_class:"control-label" }}

    In the case of REST Framework, the filter is used to add Bootstrap-specific
    classes to the forms.
    """
    html = str(value)
    match = class_re.search(html)
    if match:
        m = re.search(r'^%s$|^%s\s|\s%s\s|\s%s$' % (css_class, css_class,
                                                    css_class, css_class),
                      match.group(1))
        if not m:
            return mark_safe(class_re.sub(match.group(1) + " " + css_class,
                                          html))
    else:
        return mark_safe(html.replace('>', ' class="%s">' % css_class, 1))
    return value

def encode_cursor(self, cursor):
    """
    Given a Cursor instance, return an url with encoded cursor.
    """
    tokens = {}
    if cursor.offset != 0:
        tokens['o'] = str(cursor.offset)
    if cursor.reverse:
        tokens['r'] = '1'
    if cursor.position is not None:
        tokens['p'] = cursor.position

    querystring = parse.urlencode(tokens, doseq=True)
    encoded = b64encode(querystring.encode('ascii')).decode('ascii')
    return replace_query_param(self.base_url, self.cursor_query_param, encoded)

def _get_position_from_instance(self, instance, ordering):
    field_name = ordering[0].lstrip('-')
    if isinstance(instance, dict):
        attr = instance[field_name]
    else:
        attr = getattr(instance, field_name)
    return str(attr)

def get_paginated_response(self, data):
    return Response(OrderedDict([
        ('next', self.get_next_link()),
        ('previous', self.get_previous_link()),
        ('results', data)
    ]))

def get_html_context(self):
    return {
        'previous_url': self.get_previous_link(),
        'next_url': self.get_next_link()
    }

def to_html(self):
    template = loader.get_template(self.template)
    context = self.get_html_context()
    return template.render(context)

def select_parser(self, request, parsers):
    """
    Given a list of parsers and a media type, return the appropriate
    parser to handle the incoming request.
    """
    for parser in parsers:
        if media_type_matches(parser.media_type, request.content_type):
            return parser
    return None

def select_renderer(self, request, renderers, format_suffix=None):
    """
    Given a request and a list of renderers, return a two-tuple of:
    (renderer, media type).
    """
    # Allow URL style format override.  eg. "?format=json
    format_query_param = self.settings.URL_FORMAT_OVERRIDE
    format = format_suffix or request.query_params.get(format_query_param)

    if format:
        renderers = self.filter_renderers(renderers, format)

    accepts = self.get_accept_list(request)

    # Check the acceptable media types against each renderer,
    # attempting more specific media types first
    # NB. The inner loop here isn't as bad as it first looks :)
    #     Worst case is we're looping over len(accept_list) * len(self.renderers)
    for media_type_set in order_by_precedence(accepts):
        for renderer in renderers:
            for media_type in media_type_set:
                if media_type_matches(renderer.media_type, media_type):
                    # Return the most specific media type as accepted.
                    media_type_wrapper = _MediaType(media_type)
                    if (
                        _MediaType(renderer.media_type).precedence >
                        media_type_wrapper.precedence
                    ):
                        # Eg client requests '*/*'
                        # Accepted media type is 'application/json'
                        full_media_type = ';'.join(
                            (renderer.media_type,) +
                            tuple(
                                '{}={}'.format(key, value)
                                for key, value in media_type_wrapper.params.items()
                            )
                        )
                        return renderer, full_media_type
                    else:
                        # Eg client requests 'application/json; indent=8'
                        # Accepted media type is 'application/json; indent=8'
                        return renderer, media_type

    raise exceptions.NotAcceptable(available_renderers=renderers)

def precedence(self):
    """
    Return a precedence level from 0-3 for the media type given how specific it is.
    """
    if self.main_type == '*':
        return 0
    elif self.sub_type == '*':
        return 1
    elif not self.params or list(self.params) == ['q']:
        return 2
    return 3

def map_renderers(self, path, method):
    media_types = []
    for renderer in self.view.renderer_classes:
        # BrowsableAPIRenderer not relevant to OpenAPI spec
        if issubclass(renderer, renderers.BrowsableAPIRenderer):
            continue
        media_types.append(renderer.media_type)
    return media_types

def update(self, request, *args, **kwargs):
    partial = kwargs.pop('partial', False)
    instance = self.get_object()
    serializer = self.get_serializer(instance, data=request.data, partial=partial)
    serializer.is_valid(raise_exception=True)
    self.perform_update(serializer)

    if getattr(instance, '_prefetched_objects_cache', None):
        # If 'prefetch_related' has been applied to a queryset, we need to
        # forcibly invalidate the prefetch cache on the instance.
        instance._prefetched_objects_cache = {}

    return Response(serializer.data)

def get_serializer_info(self, serializer):
    """
    Given an instance of a serializer, return a dictionary of metadata
    about its fields.
    """
    if hasattr(serializer, 'child'):
        # If this is a `ListSerializer` then we want to examine the
        # underlying child serializer instance instead.
        serializer = serializer.child
    return OrderedDict([
        (field_name, self.get_field_info(field))
        for field_name, field in serializer.fields.items()
        if not isinstance(field, serializers.HiddenField)
    ])

def get_field_info(self, field):
    """
    Given an instance of a serializer field, return a dictionary
    of metadata about it.
    """
    field_info = OrderedDict()
    field_info['type'] = self.label_lookup[field]
    field_info['required'] = getattr(field, 'required', False)

    attrs = [
        'read_only', 'label', 'help_text',
        'min_length', 'max_length',
        'min_value', 'max_value'
    ]

    for attr in attrs:
        value = getattr(field, attr, None)
        if value is not None and value != '':
            field_info[attr] = force_str(value, strings_only=True)

    if getattr(field, 'child', None):
        field_info['child'] = self.get_field_info(field.child)
    elif getattr(field, 'fields', None):
        field_info['children'] = self.get_serializer_info(field)

    if (not field_info.get('read_only') and
        not isinstance(field, (serializers.RelatedField, serializers.ManyRelatedField)) and
            hasattr(field, 'choices')):
        field_info['choices'] = [
            {
                'value': choice_value,
                'display_name': force_str(choice_name, strings_only=True)
            }
            for choice_value, choice_name in field.choices.items()
        ]

    return field_info

def qs_exists(queryset):
    try:
        return queryset.exists()
    except (TypeError, ValueError, DataError):
        return False

def enforce_required_fields(self, attrs, serializer):
    """
    The `UniqueTogetherValidator` always forces an implied 'required'
    state on the fields it applies to.
    """
    if serializer.instance is not None:
        return

    missing_items = {
        field_name: self.missing_message
        for field_name in self.fields
        if serializer.fields[field_name].source not in attrs
    }
    if missing_items:
        raise ValidationError(missing_items, code='required')

def enforce_required_fields(self, attrs):
    """
    The `UniqueFor<Range>Validator` classes always force an implied
    'required' state on the fields they are applied to.
    """
    missing_items = {
        field_name: self.missing_message
        for field_name in [self.field, self.date_field]
        if field_name not in attrs
    }
    if missing_items:
        raise ValidationError(missing_items, code='required')

def _get_codes(detail):
    if isinstance(detail, list):
        return [_get_codes(item) for item in detail]
    elif isinstance(detail, dict):
        return {key: _get_codes(value) for key, value in detail.items()}
    return detail.code

def __iter__(self):
    for field in self.fields.values():
        yield self[field.field_name]

def __eq__(self, other):
    result = super().__eq__(other)
    if result is NotImplemented:
        return NotImplemented
    try:
        return result and self.code == other.code
    except AttributeError:
        return result

def __ne__(self, other):
    result = self.__eq__(other)
    if result is NotImplemented:
        return NotImplemented
    return not result

def __init__(self, method, detail=None, code=None):
    if detail is None:
        detail = force_str(self.default_detail).format(method=method)
    super().__init__(detail, code)

def __init__(self, media_type, detail=None, code=None):
    if detail is None:
        detail = force_str(self.default_detail).format(media_type=media_type)
    super().__init__(detail, code)

def reverse(self, viewname, args=None, kwargs=None, request=None, format=None, **extra):
    if request.version is not None:
        kwargs = {} if (kwargs is None) else kwargs
        kwargs[self.version_param] = request.version

    return super().reverse(
        viewname, args, kwargs, request, format, **extra
    )

def smart_urlquote_wrapper(matched_url):
    """
    Simple wrapper for smart_urlquote. ValueError("Invalid IPv6 URL") can
    be raised here, see issue #1386
    """
    try:
        return smart_urlquote(matched_url)
    except ValueError:
        return None

def perform_import(val, setting_name):
    """
    If the given setting is a string import notation,
    then perform the necessary import or imports.
    """
    if val is None:
        return None
    elif isinstance(val, str):
        return import_from_string(val, setting_name)
    elif isinstance(val, (list, tuple)):
        return [import_from_string(item, setting_name) for item in val]
    return val

def import_from_string(val, setting_name):
    """
    Attempt to import a class from a string representation.
    """
    try:
        return import_string(val)
    except ImportError as e:
        msg = "Could not import '%s' for API setting '%s'. %s: %s." % (val, setting_name, e.__class__.__name__, e)
        raise ImportError(msg)

def user_settings(self):
    if not hasattr(self, '_user_settings'):
        self._user_settings = getattr(settings, 'REST_FRAMEWORK', {})
    return self._user_settings

def __getattr__(self, attr):
    if attr not in self.defaults:
        raise AttributeError("Invalid API setting: '%s'" % attr)

    try:
        # Check if present in user settings
        val = self.user_settings[attr]
    except KeyError:
        # Fall back to defaults
        val = self.defaults[attr]

    # Coerce import strings into classes
    if attr in self.import_strings:
        val = perform_import(val, attr)

    # Cache the result
    self._cached_attrs.add(attr)
    setattr(self, attr, val)
    return val

def save(self, **kwargs):
    assert hasattr(self, '_errors'), (
        'You must call `.is_valid()` before calling `.save()`.'
    )

    assert not self.errors, (
        'You cannot call `.save()` on a serializer with invalid data.'
    )

    # Guard against incorrect use of `serializer.save(commit=False)`
    assert 'commit' not in kwargs, (
        "'commit' is not a valid keyword argument to the 'save()' method. "
        "If you need to access data before committing to the database then "
        "inspect 'serializer.validated_data' instead. "
        "You can also pass additional keyword arguments to 'save()' if you "
        "need to set extra attributes on the saved model instance. "
        "For example: 'serializer.save(owner=request.user)'.'"
    )

    assert not hasattr(self, '_data'), (
        "You cannot call `.save()` after accessing `serializer.data`."
        "If you need to access data before committing to the database then "
        "inspect 'serializer.validated_data' instead. "
    )

    validated_data = {**self.validated_data, **kwargs}

    if self.instance is not None:
        self.instance = self.update(self.instance, validated_data)
        assert self.instance is not None, (
            '`update()` did not return an object instance.'
        )
    else:
        self.instance = self.create(validated_data)
        assert self.instance is not None, (
            '`create()` did not return an object instance.'
        )

    return self.instance

def _get_declared_fields(cls, bases, attrs):
    fields = [(field_name, attrs.pop(field_name))
              for field_name, obj in list(attrs.items())
              if isinstance(obj, Field)]
    fields.sort(key=lambda x: x[1]._creation_counter)

    # Ensures a base class field doesn't override cls attrs, and maintains
    # field precedence when inheriting multiple parents. e.g. if there is a
    # class C(A, B), and A and B both define 'field', use 'field' from A.
    known = set(attrs)

    def visit(name):
        known.add(name)
        return name

    base_fields = [
        (visit(name), f)
        for base in bases if hasattr(base, '_declared_fields')
        for name, f in base._declared_fields.items() if name not in known
    ]

    return OrderedDict(base_fields + fields)

def __new__(cls, name, bases, attrs):
    attrs['_declared_fields'] = cls._get_declared_fields(bases, attrs)
    return super().__new__(cls, name, bases, attrs)

def visit(name):
    known.add(name)
    return name

def _writable_fields(self):
    for field in self.fields.values():
        if not field.read_only:
            yield field

def _read_only_defaults(self):
    fields = [
        field for field in self.fields.values()
        if (field.read_only) and (field.default != empty) and (field.source != '*') and ('.' not in field.source)
    ]

    defaults = OrderedDict()
    for field in fields:
        try:
            default = field.get_default()
        except SkipField:
            continue
        defaults[field.source] = default

    return defaults

def run_validators(self, value):
    """
    Add read_only fields with defaults to value before running validators.
    """
    if isinstance(value, dict):
        to_validate = self._read_only_defaults()
        to_validate.update(value)
    else:
        to_validate = value
    super().run_validators(to_validate)

def __iter__(self):
    for field in self.fields.values():
        yield self[field.field_name]

def default(self, obj):
    # For Date Time string spec, see ECMA 262
    # https://ecma-international.org/ecma-262/5.1/#sec-15.9.1.15
    if isinstance(obj, Promise):
        return force_str(obj)
    elif isinstance(obj, datetime.datetime):
        representation = obj.isoformat()
        if representation.endswith('+00:00'):
            representation = representation[:-6] + 'Z'
        return representation
    elif isinstance(obj, datetime.date):
        return obj.isoformat()
    elif isinstance(obj, datetime.time):
        if timezone and timezone.is_aware(obj):
            raise ValueError("JSON can't represent timezone-aware times.")
        representation = obj.isoformat()
        return representation
    elif isinstance(obj, datetime.timedelta):
        return str(obj.total_seconds())
    elif isinstance(obj, decimal.Decimal):
        # Serializers will coerce decimals to strings by default.
        return float(obj)
    elif isinstance(obj, uuid.UUID):
        return str(obj)
    elif isinstance(obj, QuerySet):
        return tuple(obj)
    elif isinstance(obj, bytes):
        # Best-effort for binary blobs. See #4187.
        return obj.decode()
    elif hasattr(obj, 'tolist'):
        # Numpy arrays and array scalars.
        return obj.tolist()
    elif (coreapi is not None) and isinstance(obj, (coreapi.Document, coreapi.Error)):
        raise RuntimeError(
            'Cannot return a coreapi object from a JSON view. '
            'You should be using a schema renderer instead for this view.'
        )
    elif hasattr(obj, '__getitem__'):
        cls = (list if isinstance(obj, (list, tuple)) else dict)
        try:
            return cls(obj)
        except Exception:
            pass
    elif hasattr(obj, '__iter__'):
        return tuple(item for item in obj)
    return super().default(obj)

def __getitem__(self, key):
    field = self.fields[key]
    value = self.data.get(key)
    error = self.errors.get(key) if hasattr(self, '_errors') else None
    if isinstance(field, Serializer):
        return NestedBoundField(field, value, error)
    if isinstance(field, JSONField):
        return JSONBoundField(field, value, error)
    return BoundField(field, value, error)

def data(self):
    ret = super().data
    return ReturnDict(ret, serializer=self)

def errors(self):
    ret = super().errors
    if isinstance(ret, list) and len(ret) == 1 and getattr(ret[0], 'code', None) == 'null':
        # Edge case. Provide a more descriptive error than
        # "this field may not be null", when no data is passed.
        detail = ErrorDetail('No data provided', code='null')
        ret = {api_settings.NON_FIELD_ERRORS_KEY: [detail]}
    return ReturnDict(ret, serializer=self)

def create(self, validated_data):
    return [
        self.child.create(attrs) for attrs in validated_data
    ]

def get_uniqueness_extra_kwargs(self, field_names, declared_fields, extra_kwargs):
    """
    Return any additional field options that need to be included as a
    result of uniqueness constraints on the model. This is returned as
    a two-tuple of:

    ('dict of updated extra kwargs', 'mapping of hidden fields')
    """
    if getattr(self.Meta, 'validators', None) is not None:
        return (extra_kwargs, {})

    model = getattr(self.Meta, 'model')
    model_fields = self._get_model_fields(
        field_names, declared_fields, extra_kwargs
    )

    # Determine if we need any additional `HiddenField` or extra keyword
    # arguments to deal with `unique_for` dates that are required to
    # be in the input data in order to validate it.
    unique_constraint_names = set()

    for model_field in model_fields.values():
        # Include each of the `unique_for_*` field names.
        unique_constraint_names |= {model_field.unique_for_date, model_field.unique_for_month,
                                    model_field.unique_for_year}

    unique_constraint_names -= {None}

    # Include each of the `unique_together` field names,
    # so long as all the field names are included on the serializer.
    for parent_class in [model] + list(model._meta.parents):
        for unique_together_list in parent_class._meta.unique_together:
            if set(field_names).issuperset(unique_together_list):
                unique_constraint_names |= set(unique_together_list)

    # Now we have all the field names that have uniqueness constraints
    # applied, we can add the extra 'required=...' or 'default=...'
    # arguments that are appropriate to these fields, or add a `HiddenField` for it.
    hidden_fields = {}
    uniqueness_extra_kwargs = {}

    for unique_constraint_name in unique_constraint_names:
        # Get the model field that is referred too.
        unique_constraint_field = model._meta.get_field(unique_constraint_name)

        if getattr(unique_constraint_field, 'auto_now_add', None):
            default = CreateOnlyDefault(timezone.now)
        elif getattr(unique_constraint_field, 'auto_now', None):
            default = timezone.now
        elif unique_constraint_field.has_default():
            default = unique_constraint_field.default
        else:
            default = empty

        if unique_constraint_name in model_fields:
            # The corresponding field is present in the serializer
            if default is empty:
                uniqueness_extra_kwargs[unique_constraint_name] = {'required': True}
            else:
                uniqueness_extra_kwargs[unique_constraint_name] = {'default': default}
        elif default is not empty:
            # The corresponding field is not present in the
            # serializer. We have a default to use for it, so
            # add in a hidden field that populates it.
            hidden_fields[unique_constraint_name] = HiddenField(default=default)

    # Update `extra_kwargs` with any new options.
    for key, value in uniqueness_extra_kwargs.items():
        if key in extra_kwargs:
            value.update(extra_kwargs[key])
        extra_kwargs[key] = value

    return extra_kwargs, hidden_fields

def _get_model_fields(self, field_names, declared_fields, extra_kwargs):
    """
    Returns all the model fields that are being mapped to by fields
    on the serializer class.
    Returned as a dict of 'model field name' -> 'model field'.
    Used internally by `get_uniqueness_field_options`.
    """
    model = getattr(self.Meta, 'model')
    model_fields = {}

    for field_name in field_names:
        if field_name in declared_fields:
            # If the field is declared on the serializer
            field = declared_fields[field_name]
            source = field.source or field_name
        else:
            try:
                source = extra_kwargs[field_name]['source']
            except KeyError:
                source = field_name

        if '.' in source or source == '*':
            # Model fields will always have a simple source mapping,
            # they can't be nested attribute lookups.
            continue

        try:
            field = model._meta.get_field(source)
            if isinstance(field, DjangoModelField):
                model_fields[source] = field
        except FieldDoesNotExist:
            pass

    return model_fields

def build_field(self, field_name, info, model_class, nested_depth):
    """
    Return a two tuple of (cls, kwargs) to build a serializer field with.
    """
    if field_name in info.fields_and_pk:
        model_field = info.fields_and_pk[field_name]
        return self.build_standard_field(field_name, model_field)

    elif field_name in info.relations:
        relation_info = info.relations[field_name]
        if not nested_depth:
            return self.build_relational_field(field_name, relation_info)
        else:
            return self.build_nested_field(field_name, relation_info, nested_depth)

    elif hasattr(model_class, field_name):
        return self.build_property_field(field_name, model_class)

    elif field_name == self.url_field_name:
        return self.build_url_field(field_name, model_class)

    return self.build_unknown_field(field_name, model_class)

def __setitem__(self, key, field):
    self.fields[key] = field
    field.bind(field_name=key, parent=self.serializer)

def get_nested_relation_kwargs(relation_info):
    kwargs = {'read_only': True}
    if relation_info.to_many:
        kwargs['many'] = True
    return kwargs

def save(self, *args, **kwargs):
    if not self.key:
        self.key = self.generate_key()
    return super().save(*args, **kwargs)

def match(self, other):
    """Return true if this MediaType satisfies the given MediaType."""
    for key in self.params:
        if key != 'q' and other.params.get(key, None) != self.params.get(key, None):
            return False

    if self.sub_type != '*' and other.sub_type != '*' and other.sub_type != self.sub_type:
        return False

    if self.main_type != '*' and other.main_type != '*' and other.main_type != self.main_type:
        return False

    return True

def parse_html_list(dictionary, prefix='', default=None):
    """
    Used to support list values in HTML forms.
    Supports lists of primitives and/or dictionaries.

    * List of primitives.

    {
        '[0]': 'abc',
        '[1]': 'def',
        '[2]': 'hij'
    }
        -->
    [
        'abc',
        'def',
        'hij'
    ]

    * List of dictionaries.

    {
        '[0]foo': 'abc',
        '[0]bar': 'def',
        '[1]foo': 'hij',
        '[1]bar': 'klm',
    }
        -->
    [
        {'foo': 'abc', 'bar': 'def'},
        {'foo': 'hij', 'bar': 'klm'}
    ]

    :returns a list of objects, or the value specified in ``default`` if the list is empty
    """
    ret = {}
    regex = re.compile(r'^%s\[([0-9]+)\](.*)$' % re.escape(prefix))
    for field, value in dictionary.items():
        match = regex.match(field)
        if not match:
            continue
        index, key = match.groups()
        index = int(index)
        if not key:
            ret[index] = value
        elif isinstance(ret.get(index), dict):
            ret[index][key] = value
        else:
            ret[index] = MultiValueDict({key: [value]})

    # return the items of the ``ret`` dict, sorted by key, or ``default`` if the dict is empty
    return [ret[item] for item in sorted(ret)] if ret else default

def parse_html_dict(dictionary, prefix=''):
    """
    Used to support dictionary values in HTML forms.

    {
        'profile.username': 'example',
        'profile.email': 'example@example.com',
    }
        -->
    {
        'profile': {
            'username': 'example',
            'email': 'example@example.com'
        }
    }
    """
    ret = MultiValueDict()
    regex = re.compile(r'^%s\.(.+)$' % re.escape(prefix))
    for field in dictionary:
        match = regex.match(field)
        if not match:
            continue
        key = match.groups()[0]
        value = dictionary.getlist(field)
        ret.setlist(key, value)

    return ret

def get_description(self, path, method):
    """
    Determine a path description.

    This will be based on the method docstring if one exists,
    or else the class docstring.
    """
    view = self.view

    method_name = getattr(view, 'action', method.lower())
    method_docstring = getattr(view, method_name, None).__doc__
    if method_docstring:
        # An explicit docstring on the method or action.
        return self._get_description_section(view, method.lower(), formatting.dedent(smart_str(method_docstring)))
    else:
        return self._get_description_section(view, getattr(view, 'action', method.lower()),
                                             view.get_view_description())

def _get_description_section(self, view, header, description):
    lines = [line for line in description.splitlines()]
    current_section = ''
    sections = {'': ''}

    for line in lines:
        if self.header_regex.match(line):
            current_section, separator, lead = line.partition(':')
            sections[current_section] = lead.strip()
        else:
            sections[current_section] += '\n' + line

    # TODO: SCHEMA_COERCE_METHOD_NAMES appears here and in `SchemaGenerator.get_keys`
    coerce_method_names = api_settings.SCHEMA_COERCE_METHOD_NAMES
    if header in sections:
        return sections[header].strip()
    if header in coerce_method_names:
        if coerce_method_names[header] in sections:
            return sections[coerce_method_names[header]].strip()
    return sections[''].strip()

def map_choicefield(self, field):
    choices = list(OrderedDict.fromkeys(field.choices))  # preserve order and remove duplicates
    if all(isinstance(choice, bool) for choice in choices):
        type = 'boolean'
    elif all(isinstance(choice, int) for choice in choices):
        type = 'integer'
    elif all(isinstance(choice, (int, float, Decimal)) for choice in choices):  # `number` includes `integer`
        # Ref: https://tools.ietf.org/html/draft-wright-json-schema-validation-00#section-5.21
        type = 'number'
    elif all(isinstance(choice, str) for choice in choices):
        type = 'string'
    else:
        type = None

    mapping = {
        # The value of `enum` keyword MUST be an array and SHOULD be unique.
        # Ref: https://tools.ietf.org/html/draft-wright-json-schema-validation-00#section-5.20
        'enum': choices
    }

    # If We figured out `type` then and only then we should set it. It must be a string.
    # Ref: https://swagger.io/docs/specification/data-models/data-types/#mixed-type
    # It is optional but it can not be null.
    # Ref: https://tools.ietf.org/html/draft-wright-json-schema-validation-00#section-5.21
    if type:
        mapping['type'] = type
    return mapping

def map_field(self, field):

    # Nested Serializers, `many` or not.
    if isinstance(field, serializers.ListSerializer):
        return {
            'type': 'array',
            'items': self.map_serializer(field.child)
        }
    if isinstance(field, serializers.Serializer):
        data = self.map_serializer(field)
        data['type'] = 'object'
        return data

    # Related fields.
    if isinstance(field, serializers.ManyRelatedField):
        return {
            'type': 'array',
            'items': self.map_field(field.child_relation)
        }
    if isinstance(field, serializers.PrimaryKeyRelatedField):
        model = getattr(field.queryset, 'model', None)
        if model is not None:
            model_field = model._meta.pk
            if isinstance(model_field, models.AutoField):
                return {'type': 'integer'}

    # ChoiceFields (single and multiple).
    # Q:
    # - Is 'type' required?
    # - can we determine the TYPE of a choicefield?
    if isinstance(field, serializers.MultipleChoiceField):
        return {
            'type': 'array',
            'items': self.map_choicefield(field)
        }

    if isinstance(field, serializers.ChoiceField):
        return self.map_choicefield(field)

    # ListField.
    if isinstance(field, serializers.ListField):
        mapping = {
            'type': 'array',
            'items': {},
        }
        if not isinstance(field.child, _UnvalidatedField):
            mapping['items'] = self.map_field(field.child)
        return mapping

    # DateField and DateTimeField type is string
    if isinstance(field, serializers.DateField):
        return {
            'type': 'string',
            'format': 'date',
        }

    if isinstance(field, serializers.DateTimeField):
        return {
            'type': 'string',
            'format': 'date-time',
        }

    # "Formats such as "email", "uuid", and so on, MAY be used even though undefined by this specification."
    # see: https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.2.md#data-types
    # see also: https://swagger.io/docs/specification/data-models/data-types/#string
    if isinstance(field, serializers.EmailField):
        return {
            'type': 'string',
            'format': 'email'
        }

    if isinstance(field, serializers.URLField):
        return {
            'type': 'string',
            'format': 'uri'
        }

    if isinstance(field, serializers.UUIDField):
        return {
            'type': 'string',
            'format': 'uuid'
        }

    if isinstance(field, serializers.IPAddressField):
        content = {
            'type': 'string',
        }
        if field.protocol != 'both':
            content['format'] = field.protocol
        return content

    if isinstance(field, serializers.DecimalField):
        if getattr(field, 'coerce_to_string', api_settings.COERCE_DECIMAL_TO_STRING):
            content = {
                'type': 'string',
                'format': 'decimal',
            }
        else:
            content = {
                'type': 'number'
            }

        if field.decimal_places:
            content['multipleOf'] = float('.' + (field.decimal_places - 1) * '0' + '1')
        if field.max_whole_digits:
            content['maximum'] = int(field.max_whole_digits * '9') + 1
            content['minimum'] = -content['maximum']
        self._map_min_max(field, content)
        return content

    if isinstance(field, serializers.FloatField):
        content = {
            'type': 'number',
        }
        self._map_min_max(field, content)
        return content

    if isinstance(field, serializers.IntegerField):
        content = {
            'type': 'integer'
        }
        self._map_min_max(field, content)
        # 2147483647 is max for int32_size, so we use int64 for format
        if int(content.get('maximum', 0)) > 2147483647 or int(content.get('minimum', 0)) > 2147483647:
            content['format'] = 'int64'
        return content

    if isinstance(field, serializers.FileField):
        return {
            'type': 'string',
            'format': 'binary'
        }

    # Simplest cases, default to 'string' type:
    FIELD_CLASS_SCHEMA_TYPE = {
        serializers.BooleanField: 'boolean',
        serializers.JSONField: 'object',
        serializers.DictField: 'object',
        serializers.HStoreField: 'object',
    }
    return {'type': FIELD_CLASS_SCHEMA_TYPE.get(field.__class__, 'string')}

def _map_min_max(self, field, content):
    if field.max_value:
        content['maximum'] = field.max_value
    if field.min_value:
        content['minimum'] = field.min_value

def map_serializer(self, serializer):
    # Assuming we have a valid serializer instance.
    from rest_framework.fields import empty
    required = []
    properties = {}

    for field in serializer.fields.values():
        if isinstance(field, serializers.HiddenField):
            continue

        if field.required:
            required.append(field.field_name)

        schema = self.map_field(field)
        if field.read_only:
            schema['readOnly'] = True
        if field.write_only:
            schema['writeOnly'] = True
        if field.allow_null:
            schema['nullable'] = True
        if field.default is not None and field.default != empty and not callable(field.default):
            schema['default'] = field.default
        if field.help_text:
            schema['description'] = str(field.help_text)
        self.map_field_validators(field, schema)

        properties[field.field_name] = schema

    result = {
        'type': 'object',
        'properties': properties
    }
    if required:
        result['required'] = required

    return result

def map_field_validators(self, field, schema):
    """
    map field validators
    """
    for v in field.validators:
        # "Formats such as "email", "uuid", and so on, MAY be used even though undefined by this specification."
        # https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.2.md#data-types
        if isinstance(v, EmailValidator):
            schema['format'] = 'email'
        if isinstance(v, URLValidator):
            schema['format'] = 'uri'
        if isinstance(v, RegexValidator):
            # In Python, the token \Z does what \z does in other engines.
            # https://stackoverflow.com/questions/53283160
            schema['pattern'] = v.regex.pattern.replace('\\Z', '\\z')
        elif isinstance(v, MaxLengthValidator):
            attr_name = 'maxLength'
            if isinstance(field, serializers.ListField):
                attr_name = 'maxItems'
            schema[attr_name] = v.limit_value
        elif isinstance(v, MinLengthValidator):
            attr_name = 'minLength'
            if isinstance(field, serializers.ListField):
                attr_name = 'minItems'
            schema[attr_name] = v.limit_value
        elif isinstance(v, MaxValueValidator):
            schema['maximum'] = v.limit_value
        elif isinstance(v, MinValueValidator):
            schema['minimum'] = v.limit_value
        elif isinstance(v, DecimalValidator) and \
                not getattr(field, 'coerce_to_string', api_settings.COERCE_DECIMAL_TO_STRING):
            if v.decimal_places:
                schema['multipleOf'] = float('.' + (v.decimal_places - 1) * '0' + '1')
            if v.max_digits:
                digits = v.max_digits
                if v.decimal_places is not None and v.decimal_places > 0:
                    digits -= v.decimal_places
                schema['maximum'] = int(digits * '9') + 1
                schema['minimum'] = -schema['maximum']

def get_field_kwargs(field_name, model_field):
    """
    Creates a default instance of a basic non-relational field.
    """
    kwargs = {}
    validator_kwarg = list(model_field.validators)

    # The following will only be used by ModelField classes.
    # Gets removed for everything else.
    kwargs['model_field'] = model_field

    if model_field.verbose_name and needs_label(model_field, field_name):
        kwargs['label'] = capfirst(model_field.verbose_name)

    if model_field.help_text:
        kwargs['help_text'] = model_field.help_text

    max_digits = getattr(model_field, 'max_digits', None)
    if max_digits is not None:
        kwargs['max_digits'] = max_digits

    decimal_places = getattr(model_field, 'decimal_places', None)
    if decimal_places is not None:
        kwargs['decimal_places'] = decimal_places

    if isinstance(model_field, models.SlugField):
        kwargs['allow_unicode'] = model_field.allow_unicode

    if isinstance(model_field, models.TextField) and not model_field.choices or \
            (postgres_fields and isinstance(model_field, postgres_fields.JSONField)) or \
            (hasattr(models, 'JSONField') and isinstance(model_field, models.JSONField)):
        kwargs['style'] = {'base_template': 'textarea.html'}

    if model_field.null:
        kwargs['allow_null'] = True

    if isinstance(model_field, models.AutoField) or not model_field.editable:
        # If this field is read-only, then return early.
        # Further keyword arguments are not valid.
        kwargs['read_only'] = True
        return kwargs

    if model_field.has_default() or model_field.blank or model_field.null:
        kwargs['required'] = False

    if model_field.blank and (isinstance(model_field, (models.CharField, models.TextField))):
        kwargs['allow_blank'] = True

    if not model_field.blank and (postgres_fields and isinstance(model_field, postgres_fields.ArrayField)):
        kwargs['allow_empty'] = False

    if isinstance(model_field, models.FilePathField):
        kwargs['path'] = model_field.path

        if model_field.match is not None:
            kwargs['match'] = model_field.match

        if model_field.recursive is not False:
            kwargs['recursive'] = model_field.recursive

        if model_field.allow_files is not True:
            kwargs['allow_files'] = model_field.allow_files

        if model_field.allow_folders is not False:
            kwargs['allow_folders'] = model_field.allow_folders

    if model_field.choices:
        kwargs['choices'] = model_field.choices
    else:
        # Ensure that max_value is passed explicitly as a keyword arg,
        # rather than as a validator.
        max_value = next((
            validator.limit_value for validator in validator_kwarg
            if isinstance(validator, validators.MaxValueValidator)
        ), None)
        if max_value is not None and isinstance(model_field, NUMERIC_FIELD_TYPES):
            kwargs['max_value'] = max_value
            validator_kwarg = [
                validator for validator in validator_kwarg
                if not isinstance(validator, validators.MaxValueValidator)
            ]

        # Ensure that min_value is passed explicitly as a keyword arg,
        # rather than as a validator.
        min_value = next((
            validator.limit_value for validator in validator_kwarg
            if isinstance(validator, validators.MinValueValidator)
        ), None)
        if min_value is not None and isinstance(model_field, NUMERIC_FIELD_TYPES):
            kwargs['min_value'] = min_value
            validator_kwarg = [
                validator for validator in validator_kwarg
                if not isinstance(validator, validators.MinValueValidator)
            ]

        # URLField does not need to include the URLValidator argument,
        # as it is explicitly added in.
        if isinstance(model_field, models.URLField):
            validator_kwarg = [
                validator for validator in validator_kwarg
                if not isinstance(validator, validators.URLValidator)
            ]

        # EmailField does not need to include the validate_email argument,
        # as it is explicitly added in.
        if isinstance(model_field, models.EmailField):
            validator_kwarg = [
                validator for validator in validator_kwarg
                if validator is not validators.validate_email
            ]

        # SlugField do not need to include the 'validate_slug' argument,
        if isinstance(model_field, models.SlugField):
            validator_kwarg = [
                validator for validator in validator_kwarg
                if validator is not validators.validate_slug
            ]

        # IPAddressField do not need to include the 'validate_ipv46_address' argument,
        if isinstance(model_field, models.GenericIPAddressField):
            validator_kwarg = [
                validator for validator in validator_kwarg
                if validator is not validators.validate_ipv46_address
            ]
        # Our decimal validation is handled in the field code, not validator code.
        if isinstance(model_field, models.DecimalField):
            validator_kwarg = [
                validator for validator in validator_kwarg
                if not isinstance(validator, validators.DecimalValidator)
            ]

    # Ensure that max_length is passed explicitly as a keyword arg,
    # rather than as a validator.
    max_length = getattr(model_field, 'max_length', None)
    if max_length is not None and (isinstance(model_field, (models.CharField, models.TextField, models.FileField))):
        kwargs['max_length'] = max_length
        validator_kwarg = [
            validator for validator in validator_kwarg
            if not isinstance(validator, validators.MaxLengthValidator)
        ]

    # Ensure that min_length is passed explicitly as a keyword arg,
    # rather than as a validator.
    min_length = next((
        validator.limit_value for validator in validator_kwarg
        if isinstance(validator, validators.MinLengthValidator)
    ), None)
    if min_length is not None and isinstance(model_field, models.CharField):
        kwargs['min_length'] = min_length
        validator_kwarg = [
            validator for validator in validator_kwarg
            if not isinstance(validator, validators.MinLengthValidator)
        ]

    if getattr(model_field, 'unique', False):
        validator = UniqueValidator(
            queryset=model_field.model._default_manager,
            message=get_unique_error_message(model_field))
        validator_kwarg.append(validator)

    if validator_kwarg:
        kwargs['validators'] = validator_kwarg

    return kwargs

def get_relation_kwargs(field_name, relation_info):
    """
    Creates a default instance of a flat relational field.
    """
    model_field, related_model, to_many, to_field, has_through_model, reverse = relation_info
    kwargs = {
        'queryset': related_model._default_manager,
        'view_name': get_detail_view_name(related_model)
    }

    if to_many:
        kwargs['many'] = True

    if to_field:
        kwargs['to_field'] = to_field

    limit_choices_to = model_field and model_field.get_limit_choices_to()
    if limit_choices_to:
        if not isinstance(limit_choices_to, models.Q):
            limit_choices_to = models.Q(**limit_choices_to)
        kwargs['queryset'] = kwargs['queryset'].filter(limit_choices_to)

    if has_through_model:
        kwargs['read_only'] = True
        kwargs.pop('queryset', None)

    if model_field:
        if model_field.verbose_name and needs_label(model_field, field_name):
            kwargs['label'] = capfirst(model_field.verbose_name)
        help_text = model_field.help_text
        if help_text:
            kwargs['help_text'] = help_text
        if not model_field.editable:
            kwargs['read_only'] = True
            kwargs.pop('queryset', None)
        if model_field.null:
            kwargs['allow_null'] = True
        if kwargs.get('read_only', False):
            # If this field is read-only, then return early.
            # No further keyword arguments are valid.
            return kwargs

        if model_field.has_default() or model_field.blank or model_field.null:
            kwargs['required'] = False
        if model_field.validators:
            kwargs['validators'] = model_field.validators
        if getattr(model_field, 'unique', False):
            validator = UniqueValidator(
                queryset=model_field.model._default_manager,
                message=get_unique_error_message(model_field))
            kwargs['validators'] = kwargs.get('validators', []) + [validator]
        if to_many and not model_field.blank:
            kwargs['allow_empty'] = False

    return kwargs

def get_unique_error_message(model_field):
    unique_error_message = model_field.error_messages.get('unique', None)
    if unique_error_message:
        unique_error_message = unique_error_message % {
            'model_name': model_field.model._meta.verbose_name,
            'field_label': model_field.verbose_name
        }
    return unique_error_message

def _to_camel_case(self, snake_str):
    components = snake_str.split('_')
    # We capitalize the first letter of each component except the first one
    # with the 'title' method and join them together.
    return components[0] + ''.join(x.title() for x in components[1:])

def datetime_formats(formats):
    format = ', '.join(formats).replace(
        ISO_8601,
        'YYYY-MM-DDThh:mm[:ss[.uuuuuu]][+HH:MM|-HH:MM|Z]'
    )
    return humanize_strptime(format)

def date_formats(formats):
    format = ', '.join(formats).replace(ISO_8601, 'YYYY-MM-DD')
    return humanize_strptime(format)

def time_formats(formats):
    format = ', '.join(formats).replace(ISO_8601, 'hh:mm[:ss[.uuuuuu]]')
    return humanize_strptime(format)

def as_list_of_strings(value):
    return [
        '' if (item is None) else ('%s' % item)
        for item in value
    ]

def as_form_field(self):
    value = '' if (self.value is None or self.value is False) else self.value
    return self.__class__(self._field, value, self.errors, self._prefix)

def as_form_field(self):
    value = self.value
    # When HTML form input is used and the input is not valid
    # value will be a JSONString, rather than a JSON primitive.
    if not getattr(value, 'is_json_string', False):
        try:
            value = json.dumps(
                self.value,
                sort_keys=True,
                indent=4,
                separators=(',', ': '),
            )
        except (TypeError, ValueError):
            pass
    return self.__class__(self._field, value, self.errors, self._prefix)

def as_form_field(self):
    values = {}
    for key, value in self.value.items():
        if isinstance(value, (list, dict)):
            values[key] = value
        else:
            values[key] = '' if (value is None or value is False) else force_str(value)
    return self.__class__(self._field, values, self.errors, self._prefix)

def __getitem__(self, key):
    field = self.fields[key]
    value = self.value.get(key) if self.value else None
    error = self.errors.get(key) if isinstance(self.errors, dict) else None
    if hasattr(field, 'fields'):
        return NestedBoundField(field, value, error, prefix=self.name + '.')
    elif getattr(field, '_is_jsonfield', False):
        return JSONBoundField(field, value, error, prefix=self.name + '.')
    return BoundField(field, value, error, prefix=self.name + '.')

def with_location(fields, location):
    return [
        field for field in fields
        if field.location == location
    ]

def load(*args, **kwargs):
    kwargs.setdefault('parse_constant', strict_constant)
    return json.load(*args, **kwargs)

def loads(*args, **kwargs):
    kwargs.setdefault('parse_constant', strict_constant)
    return json.loads(*args, **kwargs)

def dump(*args, **kwargs):
    kwargs.setdefault('allow_nan', False)
    return json.dump(*args, **kwargs)

def dumps(*args, **kwargs):
    kwargs.setdefault('allow_nan', False)
    return json.dumps(*args, **kwargs)

def endpoint_ordering(endpoint):
    path, method, callback = endpoint
    method_priority = {
        'GET': 0,
        'POST': 1,
        'PUT': 2,
        'PATCH': 3,
        'DELETE': 4
    }.get(method, 5)
    return (method_priority,)

def get_api_endpoints(self, patterns=None, prefix=''):
    """
    Return a list of all available API endpoints by inspecting the URL conf.
    """
    if patterns is None:
        patterns = self.patterns

    api_endpoints = []

    for pattern in patterns:
        path_regex = prefix + str(pattern.pattern)
        if isinstance(pattern, URLPattern):
            path = self.get_path_from_regex(path_regex)
            callback = pattern.callback
            if self.should_include_endpoint(path, callback):
                for method in self.get_allowed_methods(callback):
                    endpoint = (path, method, callback)
                    api_endpoints.append(endpoint)

        elif isinstance(pattern, URLResolver):
            nested_endpoints = self.get_api_endpoints(
                patterns=pattern.url_patterns,
                prefix=path_regex
            )
            api_endpoints.extend(nested_endpoints)

    return sorted(api_endpoints, key=endpoint_ordering)

def should_include_endpoint(self, path, callback):
    """
    Return `True` if the given endpoint should be included.
    """
    if not is_api_view(callback):
        return False  # Ignore anything except REST framework views.

    if callback.cls.schema is None:
        return False

    if 'schema' in callback.initkwargs:
        if callback.initkwargs['schema'] is None:
            return False

    if path.endswith('.{format}') or path.endswith('.{format}/'):
        return False  # Ignore .json style URLs.

    return True

def _initialise_endpoints(self):
    if self.endpoints is None:
        inspector = self.endpoint_inspector_cls(self.patterns, self.urlconf)
        self.endpoints = inspector.get_api_endpoints()

def check_duplicate_operation_id(self, paths):
    ids = {}
    for route in paths:
        for method in paths[route]:
            if 'operationId' not in paths[route][method]:
                continue
            operation_id = paths[route][method]['operationId']
            if operation_id in ids:
                warnings.warn(
                    'You have a duplicated operationId in your OpenAPI schema: {operation_id}\n'
                    '\tRoute: {route1}, Method: {method1}\n'
                    '\tRoute: {route2}, Method: {method2}\n'
                    '\tAn operationId has to be unique across your schema. Your schema may not work in other tools.'
                    .format(
                        route1=ids[operation_id]['route'],
                        method1=ids[operation_id]['method'],
                        route2=route,
                        method2=method,
                        operation_id=operation_id
                    )
                )
            ids[operation_id] = {
                'route': route,
                'method': method
            }

def get_schema(self, request=None, public=False):
    """
    Generate a OpenAPI schema.
    """
    self._initialise_endpoints()
    components_schemas = {}

    # Iterate endpoints generating per method path operations.
    paths = {}
    _, view_endpoints = self._get_paths_and_endpoints(None if public else request)
    for path, method, view in view_endpoints:
        if not self.has_view_permissions(path, method, view):
            continue

        operation = view.schema.get_operation(path, method)
        components = view.schema.get_components(path, method)
        for k in components.keys():
            if k not in components_schemas:
                continue
            if components_schemas[k] == components[k]:
                continue
            warnings.warn('Schema component "{}" has been overriden with a different value.'.format(k))

        components_schemas.update(components)

        # Normalise path for any provided mount url.
        if path.startswith('/'):
            path = path[1:]
        path = urljoin(self.url or '/', path)

        paths.setdefault(path, {})
        paths[path][method.lower()] = operation

    self.check_duplicate_operation_id(paths)

    # Compile final schema.
    schema = {
        'openapi': '3.0.2',
        'info': self.get_info(),
        'paths': paths,
    }

    if len(components_schemas) > 0:
        schema['components'] = {
            'schemas': components_schemas
        }

    return schema

def common_path(paths):
    split_paths = [path.strip('/').split('/') for path in paths]
    s1 = min(split_paths)
    s2 = max(split_paths)
    common = s1
    for i, c in enumerate(s1):
        if c != s2[i]:
            common = s1[:i]
            break
    return '/' + '/'.join(common)

def get_schema(self, request=None, public=False):
    """
    Generate a `coreapi.Document` representing the API schema.
    """
    self._initialise_endpoints()

    links = self.get_links(None if public else request)
    if not links:
        return None

    url = self.url
    if not url and request is not None:
        url = request.build_absolute_uri()

    distribute_links(links)
    return coreapi.Document(
        title=self.title, description=self.description,
        url=url, content=links
    )

def get_operation_id(self, path, method):
    """
    Compute an operation ID from the view type and get_operation_id_base method.
    """
    method_name = getattr(self.view, 'action', method.lower())
    if is_list_view(path, method, self.view):
        action = 'list'
    elif method_name not in self.method_mapping:
        action = self._to_camel_case(method_name)
    else:
        action = self.method_mapping[method.lower()]

    name = self.get_operation_id_base(path, method, action)

    return action + name

def get_filter_parameters(self, path, method):
    if not self.allows_filters(path, method):
        return []
    parameters = []
    for filter_backend in self.view.filter_backends:
        parameters += filter_backend().get_schema_operation_parameters(self.view)
    return parameters

def get_pagination_parameters(self, path, method):
    view = self.view

    if not is_list_view(path, method, view):
        return []

    paginator = self.get_paginator()
    if not paginator:
        return []

    return paginator.get_schema_operation_parameters(view)

def get_paginator(self):
    pagination_class = getattr(self.view, 'pagination_class', None)
    if pagination_class:
        return pagination_class()
    return None

def get_responses(self, path, method):
    if method == 'DELETE':
        return {
            '204': {
                'description': ''
            }
        }

    self.response_media_types = self.map_renderers(path, method)

    serializer = self.get_response_serializer(path, method)

    if not isinstance(serializer, serializers.Serializer):
        item_schema = {}
    else:
        item_schema = self.get_reference(serializer)

    if is_list_view(path, method, self.view):
        response_schema = {
            'type': 'array',
            'items': item_schema,
        }
        paginator = self.get_paginator()
        if paginator:
            response_schema = paginator.get_paginated_response_schema(response_schema)
    else:
        response_schema = item_schema
    status_code = '201' if method == 'POST' else '200'
    return {
        status_code: {
            'content': {
                ct: {'schema': response_schema}
                for ct in self.response_media_types
            },
            # description is a mandatory property,
            # https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.2.md#responseObject
            # TODO: put something meaningful into it
            'description': ""
        }
    }

def get_pagination_fields(self, path, method):
    view = self.view

    if not is_list_view(path, method, view):
        return []

    pagination = getattr(view, 'pagination_class', None)
    if not pagination:
        return []

    paginator = view.pagination_class()
    return paginator.get_schema_fields(view)

def get_filter_fields(self, path, method):
    if not self._allows_filters(path, method):
        return []

    fields = []
    for filter_backend in self.view.filter_backends:
        fields += filter_backend().get_schema_fields(self.view)
    return fields

def is_list_view(path, method, view):
    """
    Return True if the given path/method appears to represent a list view.
    """
    if hasattr(view, 'action'):
        # Viewsets have an explicitly defined action, which we can inspect.
        return view.action == 'list'

    if method.lower() != 'get':
        return False
    if isinstance(view, RetrieveModelMixin):
        return False
    path_components = path.strip('/').split('/')
    if path_components and '{' in path_components[-1]:
        return False
    return True

def get_path_parameters(self, path, method):
    """
    Return a list of parameters from templated path variables.
    """
    assert uritemplate, '`uritemplate` must be installed for OpenAPI schema support.'

    model = getattr(getattr(self.view, 'queryset', None), 'model', None)
    parameters = []

    for variable in uritemplate.variables(path):
        description = ''
        if model is not None:  # TODO: test this.
            # Attempt to infer a field description if possible.
            try:
                model_field = model._meta.get_field(variable)
            except Exception:
                model_field = None

            if model_field is not None and model_field.help_text:
                description = force_str(model_field.help_text)
            elif model_field is not None and model_field.primary_key:
                description = get_pk_description(model, model_field)

        parameter = {
            "name": variable,
            "in": "path",
            "required": True,
            "description": description,
            'schema': {
                'type': 'string',  # TODO: integer, pattern, ...
            },
        }
        parameters.append(parameter)

    return parameters

def get_path_fields(self, path, method):
    """
    Return a list of `coreapi.Field` instances corresponding to any
    templated path variables.
    """
    view = self.view
    model = getattr(getattr(view, 'queryset', None), 'model', None)
    fields = []

    for variable in uritemplate.variables(path):
        title = ''
        description = ''
        schema_cls = coreschema.String
        kwargs = {}
        if model is not None:
            # Attempt to infer a field description if possible.
            try:
                model_field = model._meta.get_field(variable)
            except Exception:
                model_field = None

            if model_field is not None and model_field.verbose_name:
                title = force_str(model_field.verbose_name)

            if model_field is not None and model_field.help_text:
                description = force_str(model_field.help_text)
            elif model_field is not None and model_field.primary_key:
                description = get_pk_description(model, model_field)

            if hasattr(view, 'lookup_value_regex') and view.lookup_field == variable:
                kwargs['pattern'] = view.lookup_value_regex
            elif isinstance(model_field, models.AutoField):
                schema_cls = coreschema.Integer

        field = coreapi.Field(
            name=variable,
            location='path',
            required=True,
            schema=schema_cls(title=title, description=description, **kwargs)
        )
        fields.append(field)

    return fields

def get_encoding(self, path, method):
    """
    Return the 'encoding' parameter to use for a given endpoint.
    """
    view = self.view

    # Core API supports the following request encodings over HTTP...
    supported_media_types = {
        'application/json',
        'application/x-www-form-urlencoded',
        'multipart/form-data',
    }
    parser_classes = getattr(view, 'parser_classes', [])
    for parser_class in parser_classes:
        media_type = getattr(parser_class, 'media_type', None)
        if media_type in supported_media_types:
            return media_type
        # Raw binary uploads are supported with "application/octet-stream"
        if media_type == '*/*':
            return 'application/octet-stream'

    return None

def get_pk_description(model, model_field):
    if isinstance(model_field, models.AutoField):
        value_type = _('unique integer value')
    elif isinstance(model_field, models.UUIDField):
        value_type = _('UUID string')
    else:
        value_type = _('unique value')

    return _('A {value_type} identifying this {name}.').format(
        value_type=value_type,
        name=model._meta.verbose_name,
    )

def get_request_body(self, path, method):
    if method not in ('PUT', 'PATCH', 'POST'):
        return {}

    self.request_media_types = self.map_parsers(path, method)

    serializer = self.get_request_serializer(path, method)

    if not isinstance(serializer, serializers.Serializer):
        item_schema = {}
    else:
        item_schema = self.get_reference(serializer)

    return {
        'content': {
            ct: {'schema': item_schema}
            for ct in self.request_media_types
        }
    }

def get_tags(self, path, method):
    # If user have specified tags, use them.
    if self._tags:
        return self._tags

    # First element of a specific path could be valid tag. This is a fallback solution.
    # PUT, PATCH, GET(Retrieve), DELETE:        /user_profile/{id}/       tags = [user-profile]
    # POST, GET(List):                          /user_profile/            tags = [user-profile]
    if path.startswith('/'):
        path = path[1:]

    return [path.split('/')[0].replace('_', '-')]

def form_for_link(link):
    import coreschema
    properties = OrderedDict([
        (field.name, field.schema or coreschema.String())
        for field in link.fields
    ])
    required = [
        field.name
        for field in link.fields
        if field.required
    ]
    schema = coreschema.Object(properties=properties, required=required)
    return mark_safe(coreschema.render_to_form(schema))

def is_custom_action(action):
    return action not in {
        'retrieve', 'list', 'create', 'update', 'partial_update', 'destroy'
    }

def get_keys(self, subpath, method, view):
    """
    Return a list of keys that should be used to layout a link within
    the schema document.

    /users/                   ("users", "list"), ("users", "create")
    /users/{pk}/              ("users", "read"), ("users", "update"), ("users", "delete")
    /users/enabled/           ("users", "enabled")  # custom viewset list action
    /users/{pk}/star/         ("users", "star")     # custom viewset detail action
    /users/{pk}/groups/       ("users", "groups", "list"), ("users", "groups", "create")
    /users/{pk}/groups/{pk}/  ("users", "groups", "read"), ("users", "groups", "update"), ("users", "groups", "delete")
    """
    if hasattr(view, 'action'):
        # Viewsets have explicitly named actions.
        action = view.action
    else:
        # Views have no associated action, so we determine one from the method.
        if is_list_view(subpath, method, view):
            action = 'list'
        else:
            action = self.default_mapping[method.lower()]

    named_path_components = [
        component for component
        in subpath.strip('/').split('/')
        if '{' not in component
    ]

    if is_custom_action(action):
        # Custom action, eg "/users/{pk}/activate/", "/users/active/"
        mapped_methods = {
            # Don't count head mapping, e.g. not part of the schema
            method for method in view.action_map if method != 'head'
        }
        if len(mapped_methods) > 1:
            action = self.default_mapping[method.lower()]
            if action in self.coerce_method_names:
                action = self.coerce_method_names[action]
            return named_path_components + [action]
        else:
            return named_path_components[:-1] + [action]

    if action in self.coerce_method_names:
        action = self.coerce_method_names[action]

    # Default action, eg "/users/", "/users/{pk}/"
    return named_path_components + [action]

def distribute_links(obj):
    for key, value in obj.items():
        distribute_links(value)

    for preferred_key, link in obj.links:
        key = obj.get_available_key(preferred_key)
        obj[key] = link

def get_available_key(self, preferred_key):
    if preferred_key not in self:
        return preferred_key

    while True:
        current_val = self.methods_counter[preferred_key]
        self.methods_counter[preferred_key] += 1

        key = '{}_{}'.format(preferred_key, current_val)
        if key not in self:
            return key

def get_link(self, path, method, base_url):

    if base_url and path.startswith('/'):
        path = path[1:]

    return coreapi.Link(
        url=parse.urljoin(base_url, path),
        action=method.lower(),
        encoding=self._encoding,
        fields=self._fields,
        description=self._description
    )

def handle(self, *args, **options):
    if options['generator_class']:
        generator_class = import_string(options['generator_class'])
    else:
        generator_class = self.get_generator_class()
    generator = generator_class(
        url=options['url'],
        title=options['title'],
        description=options['description'],
        urlconf=options['urlconf'],
        version=options['api_version'],
    )
    schema = generator.get_schema(request=None, public=True)
    renderer = self.get_renderer(options['format'])
    output = renderer.render(schema, renderer_context={})

    if options['file']:
        with open(options['file'], 'wb') as f:
            f.write(output)
    else:
        self.stdout.write(output.decode())

def get_renderer(self, format):
    if self.get_mode() == COREAPI_MODE:
        renderer_cls = {
            'corejson': renderers.CoreJSONRenderer,
            'openapi': renderers.CoreAPIOpenAPIRenderer,
            'openapi-json': renderers.CoreAPIJSONOpenAPIRenderer,
        }[format]
        return renderer_cls()

    renderer_cls = {
        'openapi': renderers.OpenAPIRenderer,
        'openapi-json': renderers.JSONOpenAPIRenderer,
    }[format]
    return renderer_cls()
